using System;
using UnityEngine;

public class JustFrameDashListener : MonoBehaviour
{
	private bool active;

	private bool dashing;

	private bool sliding;

	private bool waitOver;

	private int dashCounter;

	private bool dashFrameSkipped;

	private string dashSkillSlotStr;

	private string dashSkillID;

	private bool justFrameSkip;

	public Player player;

	private float justFrameTime = 0.0667f;

	private ChaosQuickStopwatch justFrameTimer;

	private float justFrameWaitTime = 0.0667f;

	private ChaosQuickStopwatch justFrameWaitTimer;

	private void Awake()
	{
		justFrameTimer = new ChaosQuickStopwatch(justFrameTime);
		justFrameWaitTimer = new ChaosQuickStopwatch(justFrameWaitTime);
	}

	private void Start()
	{
		Initialize();
	}

	private void Initialize()
	{
		if (!(this.player == null))
		{
			Player player = this.player;
			player.skillEnterEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player.skillEnterEventHandlers, new Player.SkillEventHandler(OnSkillEnter));
			Player player2 = this.player;
			player2.skillExitEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player2.skillExitEventHandlers, new Player.SkillEventHandler(OnSkillExit));
			active = true;
		}
	}

	private void Reset(bool success = false)
	{
		dashing = false;
		sliding = false;
		dashFrameSkipped = false;
		waitOver = false;
		justFrameSkip = false;
		justFrameTimer.IsRunning = false;
		justFrameWaitTimer.IsRunning = false;
		if (!success)
		{
			dashCounter = 0;
		}
	}

	private void Update()
	{
		if (!active)
		{
			return;
		}
		if (player == null)
		{
			Disable();
		}
		if (dashing)
		{
			if (!dashFrameSkipped)
			{
				dashFrameSkipped = true;
			}
			else if (player.inputDevice.GetButtonDown(dashSkillSlotStr))
			{
				Reset();
			}
		}
		else
		{
			if (!sliding)
			{
				return;
			}
			if (!player.fsm.currentStateName.Contains("Slide"))
			{
				Reset();
			}
			else if (!waitOver)
			{
				if (!justFrameWaitTimer.IsRunning)
				{
					waitOver = true;
					justFrameTimer.IsRunning = true;
				}
				else if (player.inputDevice.GetButtonDown(dashSkillSlotStr))
				{
					Reset();
				}
			}
			else if (justFrameTimer.IsRunning)
			{
				if (player.inputDevice.GetButtonDown(dashSkillSlotStr))
				{
					dashCounter++;
					PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(6, player.hurtBoxTransform.position);
					SoundManager.PlayAudio("ItemActivate", Mathf.Min(1f + (float)dashCounter * 0.2f, 2.4f), ignoreTimeRestriction: false, 0.2f);
					player.cooldownManager.LowerAllCoolDownTimers(0.1f + (float)dashCounter * 0.05f, player, showCooldownPing: true, useNormalizedVal: true);
					Reset(success: true);
					player.fsm.ChangeState(dashSkillID);
				}
			}
			else
			{
				Reset();
			}
		}
	}

	private void OnSkillEnter(Player.SkillState givenSkill)
	{
		if (!(givenSkill is Player.BaseDashState))
		{
			if (dashCounter != 0)
			{
				Reset();
			}
		}
		else
		{
			dashing = true;
			dashSkillID = player.GetDashSkill().skillID;
			dashSkillSlotStr = "Skill" + player.GetDashSkill().skillSlot;
		}
	}

	private void OnSkillExit(Player.SkillState givenSkill)
	{
		if (givenSkill is Player.BaseDashState)
		{
			dashing = false;
			sliding = true;
			justFrameWaitTimer.IsRunning = true;
		}
	}

	private void Disable()
	{
		if (this.player != null)
		{
			Player player = this.player;
			player.skillEnterEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillEnterEventHandlers, new Player.SkillEventHandler(OnSkillEnter));
			Player player2 = this.player;
			player2.skillExitEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player2.skillExitEventHandlers, new Player.SkillEventHandler(OnSkillExit));
		}
		active = false;
	}

	private void OnDestroy()
	{
		Disable();
	}
}

using System;
using UnityEngine;

[AddComponentMenu("Chaos/Components/Movement")]
public class Movement : ComponentBase
{
	public SyncedNumVarStat moveSpeedStat;

	public SyncedNumVarStat dashSpeedStat;

	public SyncedNumVarStat dashDurationStat;

	public Vector2 moveVector;

	public Vector2 dashVector;

	public float dashTimer;

	private bool dashInitiated;

	public float snapDistance = 0.12f;

	public bool moveTowards;

	public bool snapTo;

	[HideInInspector]
	public float orbitAngle;

	private bool orbitClockwise;

	public Vector2 orbitVector;

	public bool orbit;

	public float orbitSpeed = 0.1f;

	public float orbitRadius = 3f;

	private Vector2 preventVector;

	[HideInInspector]
	public bool preventUpMovement;

	[HideInInspector]
	public bool preventDownMovement;

	[HideInInspector]
	public bool preventLeftMovement;

	[HideInInspector]
	public bool preventRightMovement;

	private float calcDistance;

	private const float circlePi = (float)Math.PI * 2f;

	public void Awake()
	{
		dashTimer = dashDurationStat.CurrentValue;
	}

	public void RemoveAllPrevents(bool xAxis = true, bool yAxis = true)
	{
		if (yAxis)
		{
			preventUpMovement = false;
			preventDownMovement = false;
		}
		if (xAxis)
		{
			preventLeftMovement = false;
			preventRightMovement = false;
		}
	}

	private void PreventMovementInDirection()
	{
		if (preventUpMovement)
		{
			ZeroMovementOnAxis(xAxis: false, negative: false);
		}
		if (preventDownMovement)
		{
			ZeroMovementOnAxis(xAxis: false, negative: true);
		}
		if (preventLeftMovement)
		{
			ZeroMovementOnAxis(xAxis: true, negative: true);
		}
		if (preventRightMovement)
		{
			ZeroMovementOnAxis(xAxis: true, negative: false);
		}
	}

	private void UpdateZeroedVelocity(Vector2 moveVec)
	{
		preventVector = rigidbody2D.velocity;
		if (moveVec.x == 0f)
		{
			preventVector.x = 0f;
		}
		if (moveVec.y == 0f)
		{
			preventVector.y = 0f;
		}
		rigidbody2D.velocity = preventVector;
	}

	private void ZeroMovementOnAxis(bool xAxis, bool negative)
	{
		if (xAxis)
		{
			if (negative)
			{
				if (moveVector.x < 0f)
				{
					moveVector.x = 0f;
				}
				if (dashVector.x < 0f)
				{
					dashVector.x = 0f;
				}
			}
			else
			{
				if (moveVector.x > 0f)
				{
					moveVector.x = 0f;
				}
				if (dashVector.x > 0f)
				{
					dashVector.x = 0f;
				}
			}
		}
		else if (negative)
		{
			if (moveVector.y < 0f)
			{
				moveVector.y = 0f;
			}
			if (dashVector.y < 0f)
			{
				dashVector.y = 0f;
			}
		}
		else
		{
			if (moveVector.y > 0f)
			{
				moveVector.y = 0f;
			}
			if (dashVector.y > 0f)
			{
				dashVector.y = 0f;
			}
		}
	}

	public void MoveOnInput(ChaosInputDevice inputDev, bool useAddForce = false)
	{
		moveVector = inputDev.GetMoveVector();
		if (!(moveVector == Vector2.zero))
		{
			PreventMovementInDirection();
			bool useAddForce2 = useAddForce;
			MoveToMoveVector(0f, useAddForce2);
		}
	}

	public void MoveToMoveVector(float speed = 0f, bool useAddForce = false)
	{
		if (speed == 0f)
		{
			speed = moveSpeedStat.CurrentValue;
		}
		if (useAddForce)
		{
			rigidbody2D.AddRelativeForce(moveVector * speed, ForceMode2D.Impulse);
		}
		else
		{
			rigidbody2D.velocity = moveVector * speed;
		}
		UpdateZeroedVelocity(moveVector);
	}

	public bool MoveToTarget(Transform otherTrans, float boundRadius = 0f, float speed = 0f)
	{
		return otherTrans == null || MoveToTarget(otherTrans.position, boundRadius, speed);
	}

	public bool MoveToTarget(Vector2 target, float boundRadius = 0f, float speed = 0f, bool dryRun = false, bool endMovementOnFinish = true)
	{
		if (speed == 0f)
		{
			speed = moveSpeedStat.CurrentValue;
		}
		if (boundRadius < 0f)
		{
			moveTowards = false;
			boundRadius *= -1f;
		}
		else
		{
			moveTowards = true;
			snapTo = boundRadius == 0f;
		}
		moveVector = (target - (Vector2)transform.position).normalized;
		calcDistance = Vector2.Distance(target, transform.position);
		bool flag;
		if (moveTowards)
		{
			flag = ((!snapTo) ? (calcDistance < boundRadius) : (calcDistance < snapDistance));
		}
		else
		{
			flag = calcDistance > boundRadius;
		}
		if (dryRun)
		{
			return flag;
		}
		if (flag)
		{
			if (snapTo)
			{
				transform.position = target;
			}
			if (endMovementOnFinish)
			{
				EndMovement();
			}
		}
		else
		{
			rigidbody2D.velocity = moveVector * speed;
			UpdateZeroedVelocity(moveVector);
		}
		return flag;
	}

	public bool DashToTarget(Vector2? target = null, bool snap = false, bool ignoreDashTimer = false, bool endMovementOnFinish = true)
	{
		snapTo = snap;
		if (target.HasValue)
		{
			dashVector = (target.Value - (Vector2)transform.position).normalized;
		}
		if (snapTo)
		{
			if (Vector2.Distance(target.Value, transform.position) < snapDistance)
			{
				transform.position = target.Value;
				dashInitiated = false;
				if (endMovementOnFinish)
				{
					EndMovement();
				}
				return true;
			}
			PreventMovementInDirection();
			rigidbody2D.velocity = dashVector * dashSpeedStat.CurrentValue;
			return false;
		}
		if (!dashInitiated)
		{
			dashInitiated = true;
			dashTimer = dashDurationStat.CurrentValue;
		}
		else if (!ignoreDashTimer)
		{
			dashTimer -= Time.fixedDeltaTime;
		}
		if (dashTimer > 0f)
		{
			PreventMovementInDirection();
			rigidbody2D.velocity = dashVector * dashSpeedStat.CurrentValue;
			return false;
		}
		dashInitiated = false;
		if (endMovementOnFinish)
		{
			EndMovement();
		}
		return true;
	}

	public void InitOrbitAngle(float givenAngle, bool clockwise = true)
	{
		orbitClockwise = clockwise;
		orbitAngle = givenAngle;
		orbitVector.x = Mathf.Cos(orbitAngle);
		orbitVector.y = Mathf.Sin(0f - orbitAngle);
		if (orbitAngle < 0f || orbitAngle > (float)Math.PI * 2f)
		{
			orbitAngle = Globals.TrueMod(orbitAngle, (float)Math.PI * 2f);
		}
	}

	public void InitOrbitAngle(Vector2 normalVec, bool clockwise = true)
	{
		float num = Vector2.Angle(Vector2.up, normalVec);
		num = ((!(normalVec.x < 0f)) ? (num - 90f) : (270f - num)) * ((float)Math.PI / 180f);
		InitOrbitAngle(num, clockwise);
	}

	public void OrbitTarget(Vector2 target, bool useTransform = false)
	{
		orbitVector *= orbitRadius;
		orbitVector += target;
		if (useTransform)
		{
			transform.position = orbitVector;
		}
		else
		{
			rigidbody2D.velocity = (orbitVector - (Vector2)transform.position) * moveSpeedStat.CurrentValue;
		}
		if (orbit)
		{
			orbitAngle += orbitSpeed * Time.deltaTime * (float)(orbitClockwise ? 1 : (-1));
			if (orbitAngle >= (float)Math.PI * 2f)
			{
				orbitAngle -= (float)Math.PI * 2f;
			}
		}
		orbitVector.x = Mathf.Cos(orbitAngle);
		orbitVector.y = Mathf.Sin(0f - orbitAngle);
	}

	public void EndMovement()
	{
		dashInitiated = false;
		if (rigidbody2D != null)
		{
			rigidbody2D.velocity = Vector2.zero;
		}
	}
}
using UnityEngine;

[AddComponentMenu("Chaos/Components/Fall")]
public class Fall : ComponentBase
{
	public GameObject floorContact;

	public Collider2D fallCol;

	public bool centerFall;

	public bool disableFallTransition;

	public static float minSqrVelocityToNotFall = 400f;

	public Vector3 preFallPos;

	private bool isReady;

	private Collider2D[] pointHits = new Collider2D[10];

	public BoolVarStat ignoreFall;

	private bool ignoreFallStarted;

	private int ignoreFallStopwatchID;

	private float ignoreFallDuration = 2f;

	public PlayerHUD playerHUD;

	public bool hasIgnorePitsItem;

	private bool IsAirborne => entityScript != null && entityScript.airborneStat.CurrentValue;

	public override void Start()
	{
		base.Start();
		bool flag = true;
		if (entityScript != null && entityScript.disablePreventFallCollider)
		{
			flag = false;
		}
		int childCount = transform.childCount;
		for (int i = 0; i < childCount; i++)
		{
			GameObject gameObject = transform.GetChild(i).gameObject;
			if (flag)
			{
				if (gameObject.name.ToLower().Contains("preventfall"))
				{
					floorContact = gameObject;
					break;
				}
			}
			else if (gameObject.name.ToLower().Contains("floorcontact"))
			{
				floorContact = gameObject;
				break;
			}
		}
		if (floorContact != null)
		{
			base.Start();
			fallCol = floorContact.GetComponent<Collider2D>();
		}
		isReady = !(floorContact == null) && !(fallCol == null) && parentFSM != null;
	}

	private void Update()
	{
		if (!isReady)
		{
			enabled = false;
		}
		else
		{
			if (disableFallTransition || IsAirborne || parentFSM.currentStateName.Contains("Fall") || parentFSM.currentStateName.Contains("Dead") || rigidbody2D.velocity.sqrMagnitude >= minSqrVelocityToNotFall)
			{
				return;
			}
			if (!CheckOnPit())
			{
				preFallPos = transform.position;
				if (ignoreFallStarted)
				{
					ignoreFallStarted = false;
					if (playerHUD != null && playerHUD.castBar != null)
					{
						playerHUD.castBar.EndCast();
					}
				}
				return;
			}
			if (ignoreFall.CurrentValue)
			{
				if (!hasIgnorePitsItem)
				{
					return;
				}
				PoolManager.GetPoolItem<AirWalkEmitter>().EmitSingle(1, new Vector3(entityScript.lastTileCol, -entityScript.lastTileRow));
				if (!ignoreFallStarted)
				{
					ignoreFallStarted = true;
					ignoreFallStopwatchID = ChaosStopwatch.Begin(ignoreFallDuration);
					if (playerHUD != null && playerHUD.castBar != null)
					{
						playerHUD.castBar.StartCast(ignoreFallStopwatchID, givenStatus: false);
					}
					return;
				}
				if (!ChaosStopwatch.Check(ignoreFallStopwatchID))
				{
					return;
				}
				ignoreFallStarted = false;
				if (playerHUD != null && playerHUD.castBar != null)
				{
					playerHUD.castBar.EndCast();
				}
			}
			TransitionToFall();
		}
	}

	public bool CheckOnPit()
	{
		return fallCol != null && Physics2D.OverlapPointNonAlloc(fallCol.bounds.center, pointHits, ChaosCollisions.layerPit) > 0;
	}

	public bool CheckForFall()
	{
		return isReady && !disableFallTransition && !ignoreFall.CurrentValue && CheckOnPit();
	}

	public void TransitionToFall()
	{
		if (parentFSM.HasState("Fall"))
		{
			parentFSM.QueueChangeState("Fall");
		}
	}
}
using UnityEngine;

public class ChaosDashAttack : MonoBehaviour
{
	private static GameObject _prefab;

	public Animator anim;

	public Attack attack;

	public Transform followTrans;

	private bool destroyQueued;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ChaosDashAttack.prefab");
			}
			return _prefab;
		}
	}

	private void LateUpdate()
	{
		if (followTrans != null)
		{
			transform.position = followTrans.position;
		}
	}

	public void Stop()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			anim.Play("Fade", -1, 0f);
		}
	}

	public void Destroy()
	{
		followTrans = null;
		if (gameObject != null)
		{
			Object.Destroy(gameObject);
		}
	}
}
using UnityEngine;

public class DashAirBurst : MonoBehaviour
{
	private Animator anim;

	private void Awake()
	{
		anim = GetComponent<Animator>();
	}

	private void Start()
	{
		gameObject.SetActive(value: false);
	}

	public void Burst(Vector3 spawnLoc, Vector3 targetVec, bool useOffset = true)
	{
		BaseBurst("Burst", spawnLoc, targetVec, useOffset);
	}

	private void BaseBurst(string givenAnimName, Vector3 givenLoc, Vector3 givenVec, bool useOffset)
	{
		gameObject.SetActive(value: true);
		transform.localEulerAngles = new Vector3(0f, 0f, Vector3.Angle(Vector3.up, givenVec) * (float)((!(givenVec.x > 0f)) ? 1 : (-1)));
		transform.position = ((!useOffset) ? givenLoc : (givenLoc + givenVec));
		anim.Play(givenAnimName, -1, 0f);
	}

	public void DisableGameObject()
	{
		gameObject.SetActive(value: false);
	}
}
using UnityEngine;

public class PlayerObjects : MonoBehaviour
{
	private PlayerObjects instance;

	public PlayerObjects Instance => instance;

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad(gameObject);
	}
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using Chaos.AnimatorExtensions;
using Chaos.ArrayExtensions;
using Chaos.ListExtensions;
using Chaos.VectorExtensions;
using UnityEngine;
using UnityEngine.UI;

public class Player : Entity
{
	public delegate void EmptyEventHandler();

	public delegate void PlayerEventHandler(Player player);

	public delegate void SkillEventHandler(SkillState givenSkill);

	public delegate void AssignSkillSlotEventHandler(SkillState newSkill, int skillSlot);

	public delegate void SkillCancelEventHandler(SkillState currentSkill, SkillState prevSkill);

	public delegate void EnemyKillEventHandler(Entity entity);

	public delegate void AbsEnemyKillEventHandler(Entity entity, AttackInfo givenInfo);

	public delegate void OnSurvivalRoomEnterEventHandler(Vector3 checkPointPosition);

	public delegate void OutfitEquipEventHandler(Player player, string outfitID);

	public delegate void OutfitEquipActualEventHandler(Player player, string newOutfitID);

	public delegate void OverdriveEvent(bool ready, bool timedOut = false);

	public delegate void ParryEventHandler(AttackInfo givenInfo, Vector2 givenInputVec);

	public delegate bool SkillApplyCondition(SkillState givenSkill);

	public delegate void SkillApplyResult(SkillState givenSkill, bool givenStatus);

	public class SkillState : State<Player>
	{
		public static string staticID = string.Empty;

		public string skillID = "UnnamedSkill";

		public StatData skillData;

		public ElementType element;

		public bool isUnlocked;

		public bool hasSignatureVariant;

		public bool signatureUnlocked;

		public bool isSignature;

		public int currentLevel;

		public bool isUltimate;

		public BoolVarStat empoweredStat;

		public bool isBasic;

		public bool isDash;

		public bool isMovementSkill;

		public bool isJumpSkill;

		public bool isMeleeSkill;

		public bool isProjectileSkill;

		public bool isBuffSkill;

		public bool isSummonSkill;

		public static int MaxSkillFlags = 8;

		public float currentAnimTime;

		public float animStartTime;

		public float animHoldTime;

		public float animExecTime;

		public float cancelThreshold = 1f;

		public float runThreshold = 1f;

		public float exitThreshold = 1f;

		public Vector2 inputVector;

		public int skillSlot = -1;

		public bool isChargeSkill;

		public bool applyStopElementStatus;

		public bool disableStartCooldown;

		public bool startCooldownOnEnter = true;

		public Cooldown cooldownRef;

		public bool useSmartCD;

		public bool cdStarted;

		public bool allowSelfTransition;

		public bool allowRepeating;

		public bool repeatLock;

		public bool isHoldSkill;

		public bool holdStarted;

		public bool holdReleased;

		public bool updateHoldAnim = true;

		public bool skillExecuted;

		public SkillState prevSkillState;

		private SkillState cancelToDashSkill;

		public virtual bool IsEmpowered => empoweredStat.CurrentValue;

		public virtual string OnEnterAnimStr => parent.NextHandAnimStr;

		public virtual string OnHoldAnimStr => parent.LastHandAnimStr;

		public SkillState(string newName, FSM newFSM, Player newEnt)
			: base(newName, newFSM, newEnt)
		{
			InitializeSkill();
			skillID = newName;
			SetSkillData();
			RegisterSkill();
		}

		public void InitializeSkill()
		{
			currentLevel = 0;
			isUltimate = false;
			isUnlocked = false;
			signatureUnlocked = false;
			empoweredStat = new BoolVarStat(newBaseVal: false);
		}

		public void SetSkillData()
		{
			skillData = StatManager.GetSkillData(parent.skillCategory, skillID);
			if (skillData == null)
			{
				Debug.Log("No skillData found in StatManager for skillID: " + skillID + " in category: " + parent.skillCategory);
				return;
			}
			element = (ElementType)Enum.Parse(typeof(ElementType), skillData.GetValue<string>("elementType"));
			if (!elementSkillDict[element].Contains(skillID))
			{
				elementSkillDict[element].Add(skillID);
			}
		}

		public void RegisterSkill()
		{
			parent.skillsDict[skillID] = this;
			parent.cooldownManager.Add(skillID, skillData.GetValue<float>("cooldown", currentLevel), skillData, this);
			cooldownRef = parent.cooldownManager.cooldowns[skillID];
		}

		public virtual void SetAnimTimes(float newStart = 0f, float newHold = 0.2f, float newExecute = 0.3f, float newCancel = 0.6f, float newRun = 0.8f, float newExit = 1f)
		{
			animStartTime = newStart;
			animHoldTime = newHold;
			animExecTime = newExecute;
			cancelThreshold = newCancel;
			runThreshold = newRun;
			exitThreshold = newExit;
		}

		public void InitChargeSkillSettings(int maxCharges, float delayBetweenCharges, StatData statData, SkillState skillState)
		{
			isChargeSkill = true;
			cooldownRef.isChargeSkill = true;
			cooldownRef.chargeCount = maxCharges;
			cooldownRef.MaxChargeCount = maxCharges;
			cooldownRef.chargeDelayTime = delayBetweenCharges;
			cooldownRef.statData = statData;
			cooldownRef.skillState = skillState;
			cooldownRef.remainingTimeStopwatchID = -1;
			cooldownRef.delayStopwatchID = -1;
		}

		public virtual void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			empoweredStat.Modify(givenMod, givenStatus);
			if (parent.skillEmpowerEventHandlers != null)
			{
				parent.skillEmpowerEventHandlers(this);
			}
		}

		public virtual bool IsReady()
		{
			if ((isMovementSkill && !parent.MovementEnabled) || (isUltimate && !IsOverdriveReady()) || (!isUltimate && !cooldownRef.Ready))
			{
				return false;
			}
			if (allowSelfTransition && !allowRepeating && repeatLock)
			{
				return false;
			}
			return true;
		}

		public virtual bool IsOverdriveReady()
		{
			return true;
		}

		public bool Transition()
		{
			if (!IsReady() || (!allowSelfTransition && fsm.currentStateName == skillID))
			{
				return false;
			}
			fsm.ChangeState(skillID, allowSelfTransition: true);
			return true;
		}

		public int SetSkillSlot()
		{
			for (int i = 0; i < parent.assignedSkills.Length; i++)
			{
				if (parent.assignedSkills[i] != null && parent.assignedSkills[i].skillID == skillID)
				{
					skillSlot = i;
					return skillSlot;
				}
			}
			skillSlot = -1;
			return skillSlot;
		}

		public void SetRepeatLock(bool setLock = true)
		{
			repeatLock = setLock;
		}

		public void UpdateRepeatLock(string buttonName = "")
		{
			if (skillSlot != -1)
			{
				if (buttonName == string.Empty)
				{
					buttonName = "Skill" + skillSlot;
				}
				if (parent.inputDevice.GetButtonUp(buttonName))
				{
					SetRepeatLock(setLock: false);
				}
			}
		}

		public virtual void StartCooldownTimer(float overrideValue = -1f, bool expendCharge = true)
		{
			if (useSmartCD)
			{
				if (cdStarted)
				{
					return;
				}
				cdStarted = true;
			}
			if ((skillData.GetValue<float>("cooldown") == 0f && overrideValue == -1f) || parent == null || parent.gameObject == null || !parent.gameObject.activeSelf)
			{
				return;
			}
			if (isChargeSkill)
			{
				if (expendCharge && cooldownRef.chargeCount > 0)
				{
					cooldownRef.chargeCount = Mathf.Max(0, cooldownRef.chargeCount - ((!(overrideValue > 0f)) ? 1 : ((int)overrideValue)));
				}
				parent.StartCoroutine(parent.cooldownManager.StartChargeCounter(skillID));
			}
			else
			{
				parent.cooldownManager.StartCooldownTimer(skillID, overrideValue);
			}
		}

		public void ApplyStopElement()
		{
			if (parent.dotManager != null)
			{
				parent.dotManager.ApplyStopElement(element);
			}
		}

		public void BaseOnEnter()
		{
			SetRepeatLock();
			SetSkillSlot();
			if (parent.skillEnterEventHandlers != null)
			{
				parent.skillEnterEventHandlers(this);
			}
			if (fsm.previousState is SkillState)
			{
				prevSkillState = fsm.previousState as SkillState;
				if (isBasic)
				{
					if (!prevSkillState.isBasic && parent.cancelToBasicEventHandlers != null)
					{
						parent.cancelToBasicEventHandlers(this, prevSkillState);
					}
				}
				else if (prevSkillState.isBasic && parent.cancelFromBasicEventHandlers != null)
				{
					parent.cancelFromBasicEventHandlers(this, prevSkillState);
				}
				else if (isDash && parent.cancelToDashEventHandlers != null)
				{
					parent.cancelToDashEventHandlers(this, prevSkillState);
				}
			}
			cdStarted = false;
			if (!disableStartCooldown && startCooldownOnEnter)
			{
				StartCooldownTimer();
			}
			if (applyStopElementStatus)
			{
				ApplyStopElement();
			}
		}

		public override void OnEnter()
		{
			BaseOnEnter();
			inputVector = parent.GetInputVector();
			parent.anim.PlayDirectional(OnEnterAnimStr, -1, animStartTime);
			holdStarted = false;
			holdReleased = false;
			skillExecuted = false;
		}

		public override void Update()
		{
			UpdateRepeatLock(string.Empty);
			if (skillExecuted)
			{
				ConcludeSkill();
			}
			else if (isHoldSkill)
			{
				if (holdReleased)
				{
					ExecuteSkill();
				}
				else if (holdStarted)
				{
					HandleHoldButton();
				}
				else
				{
					holdStarted = parent.anim.AnimPlayed(animHoldTime);
				}
			}
			else if (parent.anim.AnimPlayed(animExecTime))
			{
				ExecuteSkill();
			}
		}

		public virtual void HandleHoldButton()
		{
			inputVector = GetInputVector();
			if (updateHoldAnim)
			{
				parent.anim.PlayDirectional(OnHoldAnimStr, -1, animHoldTime);
			}
			holdReleased = !parent.inputDevice.GetButton("Skill" + skillSlot);
		}

		public virtual void ExecuteSkill()
		{
			skillExecuted = true;
			AnnounceSkillExecuteEvent();
		}

		public virtual void AnnounceSkillExecuteEvent()
		{
			if (parent.skillExecEventHandlers != null)
			{
				parent.skillExecEventHandlers(this);
			}
		}

		public virtual void ConcludeSkill()
		{
			ExitToSkillOrRunOrIdle();
		}

		public override void OnExit()
		{
			if (allowSelfTransition && !allowRepeating && GetType() != fsm.nextState.GetType())
			{
				SetRepeatLock(setLock: false);
			}
			if (!disableStartCooldown && !startCooldownOnEnter)
			{
				StartCooldownTimer();
			}
			if (parent.skillExitEventHandlers != null)
			{
				parent.skillExitEventHandlers(this);
			}
		}

		public void SetSkillLevel(int skillLevel)
		{
			currentLevel = skillLevel;
			skillData.currentLevel = skillLevel;
		}

		public Vector2 GetInputVector(bool faceInputVector = true, bool useAimVector = true, bool ignoreZero = true)
		{
			return parent.GetInputVector(faceInputVector, useAimVector, ignoreZero);
		}

		public bool CancelToDash(bool enableButtonHeld = false)
		{
			cancelToDashSkill = parent.GetDashSkill();
			return cancelToDashSkill != null && parent.TransitionToSkill(cancelToDashSkill.SetSkillSlot(), enableButtonHeld);
		}

		public bool CancelToSkills(bool overrideThresholdReq = false)
		{
			return (overrideThresholdReq || parent.anim.AnimPlayed(cancelThreshold)) && parent.HandleSkills(allowButtonHeld: true, string.Empty);
		}

		public virtual bool ExitToSkillOrRunOrIdle()
		{
			currentAnimTime = parent.anim.GetAnimTime();
			if (currentAnimTime >= cancelThreshold && parent.HandleSkills(allowButtonHeld: true, string.Empty))
			{
				return true;
			}
			if (currentAnimTime >= runThreshold && GetInputVector(faceInputVector: false, useAimVector: false, ignoreZero: false) != Vector2.zero)
			{
				fsm.ChangeState("Run");
				return true;
			}
			if (currentAnimTime >= exitThreshold)
			{
				fsm.ChangeState(fsm.defaultStateName);
				return true;
			}
			return false;
		}

		public T ChaosInst<T>(GameObject givenPrefab, Vector2? givenPosition = null, Quaternion? givenQuaternion = null, Transform parentTransform = null)
		{
			return Globals.ChaosInst<T>(givenPrefab, parentTransform ?? parent.transform.parent, (!givenPosition.HasValue) ? ((Vector2)parent.attackOriginTrans.position) : givenPosition.Value, (!givenQuaternion.HasValue) ? Quaternion.identity : givenQuaternion.Value);
		}

		public void SetTargetLineVars(bool groundBased = true, bool stopOnDestructible = true, bool stopOnEnemy = true)
		{
			parent.targetLine.SetCollisionLayerMask((!groundBased) ? "TargetLineAir" : "TargetLineGround", stopOnDestructible, stopOnEnemy, (skillData != null) ? skillData.GetValue<List<string>>("targetNames") : null);
		}

		public void SetAttackInfo(Attack givenAtk)
		{
			givenAtk.SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
		}
	}

