public class RunState : State<Player>
{
	private static GameObject fxPrefab;

	private GameObject fxObj;

	private static string modStrID = "PlayerRunState";

	private SkillState dashSkill;

	private bool moveSpeedApplied;

	private int speedupStopwatchID = -1;

	private NumVarStatMod moveSpeedMod;

	private float currentMSPercentage;

	private NumVarStatMod animSpeedMod;

	private ChaosQuickStopwatch animStopwatch = new ChaosQuickStopwatch(0.25f);

	private FacingDirection inputDir;

	private ChaosQuickStopwatch parryStopwatch;

	private Vector2 currMoveVec = Vector2.zero;

	private Vector2 lastMoveVec = Vector2.zero;

	public static GameObject FXPrefab => fxPrefab ?? (fxPrefab = ChaosBundle.Get("Assets/Prefabs/Effects/AirRunEffect.prefab"));

	public RunState(string stateName, FSM parentFSM, Player parentEntity)
		: base(stateName, parentFSM, parentEntity)
	{
		moveSpeedMod = new NumVarStatMod(modStrID, 0.4f, 10, VarStatModType.LateMultiplicative);
		animSpeedMod = new NumVarStatMod(modStrID, 1f, 1, VarStatModType.Override);
		parryStopwatch = new ChaosQuickStopwatch(parent.parryActiveTime);
	}

	public override void OnEnter()
	{
		parent.anim.PlayDirectional(name + parent.facingDirection);
		speedupStopwatchID = ChaosStopwatch.Begin(parent.runSpeedupStat.CurrentValue);
		moveSpeedApplied = false;
		dashSkill = parent.GetDashSkill();
		if (parent.parryAvailStat.CurrentValue)
		{
			parent.parryActive = true;
			parryStopwatch.IsRunning = true;
		}
	}

	public override void FixedUpdate()
	{
		if (parent.parryAvailStat.CurrentValue)
		{
			if (parent.parryActive)
			{
				parent.parryActive = parryStopwatch.IsRunning;
			}
			else if (currMoveVec != Vector2.zero && Vector2.Angle(currMoveVec, lastMoveVec) > 100f)
			{
				parent.parryActive = true;
				parryStopwatch.IsRunning = true;
			}
		}
	}

	public override void Update()
	{
		if (parent.HandleSkills(allowButtonHeld: false, string.Empty))
		{
			return;
		}
		inputDir = GetInputDirection(parent.inputDevice);
		if (inputDir == FacingDirection.Neutral)
		{
			if (moveSpeedApplied)
			{
				parent.movement.dashVector = parent.movement.moveVector;
				fsm.ChangeState(SlideState.staticID);
			}
			else
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
			return;
		}
		if (parent.facingDirection != inputDir)
		{
			parent.facingDirection = inputDir;
			parent.anim.PlayDirectional(name + parent.facingDirection);
		}
		parent.movement.MoveOnInput(parent.inputDevice);
		lastMoveVec = currMoveVec;
		currMoveVec = parent.movement.moveVector;
		if (dashSkill != null && !moveSpeedApplied && ChaosStopwatch.Check(speedupStopwatchID))
		{
			moveSpeedApplied = true;
			parent.movement.moveSpeedStat.AddMod(moveSpeedMod);
			PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attackOriginTrans.position, parent.GetInputVector(faceInputVector: false, useAimVector: false, ignoreZero: false));
			SoundManager.PlayWithDistAndSPR("RunSpeed", parent.transform.position);
		}
		HandleAnimSpeed();
	}

	public override void OnExit()
	{
		parent.movement.EndMovement();
		parent.movement.moveSpeedStat.RemoveMod(moveSpeedMod);
		parent.animSpeedHandler.Modify(animSpeedMod, givenStatus: false);
		parent.parryActive = false;
	}

	private void HandleAnimSpeed()
	{
		if (!animStopwatch.IsRunning)
		{
			animStopwatch.IsRunning = true;
			currentMSPercentage = parent.movement.moveSpeedStat.CurrentValue / parent.movement.moveSpeedStat.BaseValue;
			animSpeedMod.modValue = currentMSPercentage;
			parent.animSpeedHandler.Modify(animSpeedMod, givenStatus: true);
		}
	}
}

public class ParryState : State<Player>
{
	private NumVarStatMod parryMoveSpeedMod;

	private ChaosQuickStopwatch parryStopwatch = new ChaosQuickStopwatch(0.25f);

	public static readonly string staticID = "PlayerParry";

	public ParryState(FSM fsm, Player ent)
		: base(staticID, fsm, ent)
	{
		parryMoveSpeedMod = new NumVarStatMod(staticID, 7f, 10, VarStatModType.OverrideWithMods);
	}

	public override void OnEnter()
	{
		parent.FaceTarget(parent.transform.position - (Vector3)parent.movement.dashVector);
		parent.anim.PlayDirectional(parent.BackhandAnimStr, -1, 0.27f);
		parent.movement.moveVector = parent.movement.dashVector;
		parent.movement.moveSpeedStat.AddMod(parryMoveSpeedMod);
		parent.movement.MoveToMoveVector();
		parryStopwatch.IsRunning = true;
	}

	public override void FixedUpdate()
	{
		if (!parryStopwatch.IsRunning && !parent.HandleSkills(allowButtonHeld: true, parent.GetDashSkill().name))
		{
			if (parent.MovementEnabled && parent.inputDevice.GetMoveVector() != Vector2.zero)
			{
				fsm.ChangeState("Run");
			}
			else
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
		}
	}

	public override void OnExit()
	{
		parent.movement.moveSpeedStat.RemoveMod(parryMoveSpeedMod);
		parent.movement.EndMovement();
	}
}

public class SlideState : State<Player>
{
	private ChaosQuickStopwatch slideStopwatch = new ChaosQuickStopwatch(0.25f);

	public float slideSpeed = 5f;

	private bool finishedSliding;

	private bool ignoreSlide;

	private int currentIgnoreCount;

	private int maxIgnoreCount = 2;

	private SkillState dashSkill;

	private NumVarStatMod slideMoveSpeedMod;

	private float dustAngle;

	private BoolVarStatMod airborneMod;

	public static readonly string staticID = "PlayerSlide";

	public SlideState(FSM fsm, Player ent)
		: base(staticID, fsm, ent)
	{
		slideMoveSpeedMod = new NumVarStatMod(staticID, 0f, 10, VarStatModType.OverrideWithMods);
		airborneMod = new BoolVarStatMod(staticID, newModValue: true);
	}

	public override void OnEnter()
	{
		parent.anim.PlayDirectional(parent.SlideAnimStr);
		parent.movement.moveVector = parent.movement.dashVector;
		parent.dashSlideIgnored = false;
		ignoreSlide = parent.ignoreDashSlide.CurrentValue && currentIgnoreCount < maxIgnoreCount;
		if (ignoreSlide)
		{
			parent.airborneStat.AddMod(airborneMod);
			parent.TogglePreventFallCollider(status: false);
		}
		dashSkill = parent.GetDashSkill();
		dustAngle = Globals.GetRotationVector(parent.movement.dashVector).z;
		slideStopwatch.IsRunning = true;
		finishedSliding = false;
	}

	public override void Update()
	{
		if (finishedSliding)
		{
			if (!parent.HandleSkills(allowButtonHeld: true, (dashSkill != null) ? dashSkill.skillID : string.Empty))
			{
				if (parent.MovementEnabled && parent.inputDevice.GetMoveVector() != Vector2.zero)
				{
					fsm.ChangeState("Run");
				}
				else
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
			}
		}
		else if (ignoreSlide && dashSkill != null && parent.inputDevice.GetButton("Skill" + dashSkill.skillSlot))
		{
			parent.dashSlideIgnored = true;
			dashSkill.Transition();
		}
	}

	public override void FixedUpdate()
	{
		if (!finishedSliding)
		{
			finishedSliding = !slideStopwatch.IsRunning;
			slideMoveSpeedMod.modValue = Mathf.Lerp(slideSpeed * 0.5f, slideSpeed, slideStopwatch.TimePercentage);
			parent.movement.moveSpeedStat.AddMod(slideMoveSpeedMod);
			parent.movement.MoveToMoveVector();
			parent.dustEmitter.EmitDirBurst(1, 0f - dustAngle, 10f, -1f, 0.75f);
		}
	}

	public override void OnExit()
	{
		if (dashSkill != null && fsm.nextState == dashSkill)
		{
			currentIgnoreCount++;
		}
		else
		{
			currentIgnoreCount = 0;
		}
		parent.airborneStat.RemoveMod(airborneMod);
		parent.TogglePreventFallCollider(status: true);
		parent.movement.moveSpeedStat.RemoveMod(slideMoveSpeedMod);
		parent.movement.EndMovement();
	}
}

