public new class DeadState : State<Player>
{
	private GameObject ghostPrefab;

	private GameObject currentGhost;

	private ChaosQuickStopwatch resurrectStopwatch = new ChaosQuickStopwatch(1.5f);

	private ResurrectItem currentResItem;

	private bool resAvailable;

	private bool resQueued;

	private bool deathSummaryQueued;

	private bool deathSummaryActivated;

	private int deathSummaryStopwatchID;

	private float deathSummaryDelay = 1f;

	private bool kneesHitFloor;

	private bool bodyHitFloor;

	public DeadState(string stateName, FSM parentFSM, Player parentEntity)
		: base(stateName, parentFSM, parentEntity)
	{
		ghostPrefab = ChaosBundle.Get("Assets/Prefabs/Player/Ghost.prefab");
		currentGhost = null;
	}

	public override void OnEnter()
	{
		if (parent.fall.CheckOnPit())
		{
			fsm.ChangeState("Fall");
			return;
		}
		parent.facingDirection = FacingDirection.Right;
		parent.isFacingRight = true;
		parent.anim.PlayDirectional("DeadDown");
		GameController.players.Remove(parent.gameObject);
		GameController.allies.Remove(parent.gameObject);
		parent.hud.ToggleBars(enable: false);
		deathSummaryQueued = false;
		deathSummaryActivated = false;
		kneesHitFloor = false;
		bodyHitFloor = false;
		parent.hurtBoxCollider.enabled = false;
		parent.floorCollider.enabled = false;
		if (Application.loadedLevelName.Contains("PvP") || GameController.pvpOn)
		{
			return;
		}
		TimeScaleController.StandardFreezeIntoEaseOutTimeScale();
		currentResItem = parent.inventory.GetResurrectItem();
		resAvailable = currentResItem != null;
		if (resAvailable)
		{
			resQueued = false;
			resurrectStopwatch.IsRunning = true;
			return;
		}
		if (GameController.AllPlayersDead())
		{
			SoundManager.BGMPaused = true;
			deathSummaryQueued = true;
			deathSummaryStopwatchID = ChaosStopwatch.Begin(deathSummaryDelay);
		}
		else if (parent.spawnGhostOnDeath && currentGhost == null)
		{
			Ghost component = UnityEngine.Object.Instantiate(ghostPrefab, parent.transform.position, Quaternion.identity).GetComponent<Ghost>();
			currentGhost = component.gameObject;
			component.parentPlayer = parent;
			component.inputDevice = parent.inputDevice;
		}
		GameDataManager.gameData.UpdateIntStat(GameData.Stat.Death);
		GameDataManager.Save();
	}

	public override void Update()
	{
		if (!kneesHitFloor && parent.anim.AnimPlayed(0.33f))
		{
			kneesHitFloor = true;
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 10;
			float scale = 0.25f;
			float startSpeed = 3f;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitCircle(particleCount, scale, startSpeed, -1f, emitPosition);
		}
		if (!bodyHitFloor && parent.anim.AnimPlayed(0.94f))
		{
			bodyHitFloor = true;
			DustEmitter poolItem2 = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 10;
			float startSpeed = 0.25f;
			float scale = 3f;
			Vector3? emitPosition = parent.transform.position;
			poolItem2.EmitCircle(particleCount, startSpeed, scale, -1f, emitPosition);
		}
		if (resAvailable)
		{
			HandleResurrect();
		}
		else if (deathSummaryQueued && !deathSummaryActivated && ChaosStopwatch.Check(deathSummaryStopwatchID))
		{
			deathSummaryActivated = true;
			GameController.pauseTimer = true;
			GameUI.deathSummary.Activate();
			if (!Level.isBossRushMode && GameController.loopCount > 0)
			{
				RunHistoryEntry.Save();
			}
		}
	}

	public override void OnExit()
	{
		if (parent.deathMenu != null)
		{
			parent.deathMenu.SetActive(value: false);
		}
		parent.hurtBoxCollider.enabled = true;
		parent.floorCollider.enabled = true;
	}

	private void HandleResurrect()
	{
		if (resurrectStopwatch.IsRunning)
		{
			return;
		}
		if (resQueued)
		{
			if (parent.anim.AnimPlayed())
			{
				currentResItem.ResurrectPlayer();
			}
			return;
		}
		parent.overheadPrompt.DisplayPrompt("Confirm", loop: true);
		if (parent.inputDevice.GetButtonDown("Confirm"))
		{
			resQueued = true;
			parent.overheadPrompt.HidePrompt(string.Empty);
			parent.anim.Play("GetUp", -1, 0f);
			SoundManager.PlayAudio("Resurrect");
		}
	}
}

public class PlayerFallState : FallState
{
	public new Player parent;

	private bool playerAlive;

	private bool damageTaken;

	private Vector2 otherPlayerPos;

	private float fallDelay = 1f;

	private new int fallDelayStopwatchID;

	private AttackInfo fallAtkInfo;

	private Vector2 respawnLoc;

	public PlayerFallState(string stateName, FSM parentFSM, Player parentEntity)
		: base(stateName, parentFSM, parentEntity)
	{
		parent = parentEntity;
		fallAtkInfo = new AttackInfo();
		fallAtkInfo.skillID = "Pit";
		fallAtkInfo.damage = 0;
		fallAtkInfo.canHitStun = false;
		fallAtkInfo.critHitChance = 0f;
		fallAtkInfo.isStatusEffect = true;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		otherPlayerPos = Vector2.zero;
		playerAlive = true;
		damageTaken = false;
		parent.anim.PlayDirectional("Hurt" + ((!parent.multiAnimHurt) ? string.Empty : parent.facingDirection.ToString()));
		GameDataManager.gameData.gameStats.UpdateIntStatValue(GameData.Stat.Fall);
		parent.hurtBoxCollider.enabled = false;
		GameController.allies.Remove(parent.gameObject);
	}

	public override void Update()
	{
		base.Update();
		if (!finishedFalling)
		{
			return;
		}
		if (!damageTaken)
		{
			damageTaken = true;
			playerAlive = TakeFallDamage();
			fallDelayStopwatchID = ChaosStopwatch.Begin(fallDelay);
		}
		if (!ChaosStopwatch.Check(fallDelayStopwatchID) && playerAlive)
		{
			return;
		}
		if (GameController.coopOn && !GameController.pvpOn && !Application.loadedLevelName.Contains("PvP"))
		{
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (player.playerID != parent.playerID && !player.fsm.currentStateName.Contains("Dead") && !player.fsm.currentStateName.Contains("Fall"))
				{
					otherPlayerPos = player.transform.position;
				}
			}
		}
		if (otherPlayerPos != Vector2.zero && Globals.CheckCircle(otherPlayerPos, 0.25f, ChaosCollisions.layerPit) && Vector2.Distance(parent.transform.position, otherPlayerPos) >= 10f)
		{
			respawnLoc = otherPlayerPos;
		}
		else
		{
			respawnLoc = Entity.GetAvailableNearbyLocation(parent.fall.preFallPos);
			if (respawnLoc == Vector2.zero)
			{
				respawnLoc = parent.lastCheckpoint;
			}
		}
		if (playerAlive)
		{
			parent.RequestTeleportMoveToLocation(respawnLoc);
			return;
		}
		parent.transform.position = respawnLoc;
		SpawnAllyPortal(parent.transform.position);
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.hurtBoxCollider.enabled = true;
		GameController.allies.Add(parent.gameObject);
	}

	public bool TakeFallDamage()
	{
		parent.health.showHitSpark = false;
		fallAtkInfo.damage = Mathf.FloorToInt(parent.FallDamage.CurrentValue);
		parent.health.TakeDamage(fallAtkInfo, null, critPreCalculated: true);
		parent.health.showHitSpark = true;
		PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Medium, parent.transform.position, parent.transform.position + Vector3.down * 2f, Health.playerHitSparkPSysOverride);
		return parent.health.healthStat.CurrentValue > 0f;
	}
}

public class PlayerTeleToLocState : State<Player>
{
	private BoolVarStatMod airborneMod;

	private FallMoveEffect currentFMEffect;

	private bool moveCompleted;

	private ChaosQuickStopwatch moveStopwatch = new ChaosQuickStopwatch(0.2f);

	private float moveLerpValue;

	public PlayerTeleToLocState(string newName, FSM newFSM, Player newPlayer)
		: base(newName, newFSM, newPlayer)
	{
		airborneMod = new BoolVarStatMod(newName, newModValue: true);
	}

	public override void OnEnter()
	{
		parent.anim.PlayDirectional("Hurt" + parent.facingDirection);
		ToggleTeleVars(givenStatus: false);
		GameController.allies.Remove(parent.gameObject);
		moveStopwatch.IsRunning = true;
		moveCompleted = false;
		if (currentFMEffect != null)
		{
			currentFMEffect.Reset();
		}
		currentFMEffect = Globals.ChaosInst<FallMoveEffect>(FallMoveEffect.Prefab, parent.playerObjTrans, parent.attackOriginTrans.position);
		currentFMEffect.followTransform = parent.transform;
		SoundManager.PlayAudioWithDistance("FallRecover", parent.transform.position);
		if (parent.throwScript != null)
		{
			parent.throwScript.EndThrow(parent.transform.position);
		}
	}

	public override void Update()
	{
		if (moveCompleted)
		{
			SpawnAllyPortal(parent.transform.position);
			fsm.ChangeState(fsm.defaultStateName);
		}
	}

	public override void FixedUpdate()
	{
		if (!moveCompleted)
		{
			moveLerpValue = moveStopwatch.TimePercentage;
			parent.transform.position = Vector2.Lerp(parent.transform.position, parent.reqTeleLocation, moveLerpValue);
			if (moveLerpValue >= 1f)
			{
				moveCompleted = true;
			}
		}
	}

	public override void OnExit()
	{
		ToggleTeleVars(givenStatus: true);
		GameController.allies.Add(parent.gameObject);
		if (currentFMEffect != null)
		{
			currentFMEffect.Reset();
		}
	}

	private void ToggleTeleVars(bool givenStatus)
	{
		parent.spriteRenderer.enabled = givenStatus;
		parent.shadowSprite.enabled = givenStatus;
		parent.airborneStat.Modify(airborneMod, !givenStatus);
		parent.hurtBoxCollider.enabled = givenStatus;
		parent.floorContact.gameObject.SetActive(givenStatus);
		parent.TogglePreventFallCollider(givenStatus);
	}
}

public class PlayerFrozenState : FrozenState
{
	public new Player parent;

	private FacingDirection lastInputDir;

	private FacingDirection curInputDir;

	public PlayerFrozenState(string stateName, FSM parentFSM, Player parentEntity)
		: base(stateName, parentFSM, parentEntity)
	{
		parent = parentEntity;
	}

	public override void OnEnter()
	{
		durationMultiplier = ((!GameController.pvpOn) ? 1f : 0.375f);
		base.OnEnter();
		lastInputDir = GetInputDirection(parent.inputDevice);
		parent.overheadPrompt.PlayShakeAnalog(2f);
		SoundManager.PlayAudio("Frozen");
	}

	public override void Update()
	{
		if (!ChaosStopwatch.Check(freezeStopwatchID))
		{
			curInputDir = GetInputDirection(parent.inputDevice);
			if (curInputDir != lastInputDir)
			{
				SoundManager.PlayAudio("Frozen");
				ChaosStopwatch.ReduceTimeRemaining(freezeStopwatchID, 0.05f);
			}
			lastInputDir = curInputDir;
		}
		else
		{
			fsm.ChangeState(fsm.defaultStateName);
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.overheadPrompt.HidePrompt("ShakeAnalog");
	}
}

public class AirChannelDash : BaseDashState
{
	public new static string staticID = "AirChannelDash";

	private static float hitDelay = 0.02f;

	private int hitStopwatchID;

	private bool hitCompleted;

	private int maxSpawnCount = 3;

	private int spawnCount;

	private Vector2 perpendVec;

	private WindArcherChargedArrow curArrow;

	private Vector2 calcPos;

	private float calcDelay;

	public AirChannelDash(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		isProjectileSkill = true;
		InitChargeSkillSettings(1, 0f, skillData, this);
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		maxSpawnCount = ((!IsEmpowered) ? 3 : 5);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		if (cooldownReady)
		{
			hitCompleted = false;
			hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, hitDelay, maxSpawnCount);
			spawnCount = 0;
			perpendVec = Globals.GetPerpendicular(inputVector);
		}
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (!hitCompleted)
		{
			switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
			{
			case StopwatchState.Ready:
				spawnCount++;
				SpawnArrow((Vector2)parent.attackOriginTrans.position + inputVector * 1.5f, spawnCount);
				break;
			case StopwatchState.Done:
				hitCompleted = true;
				break;
			}
		}
	}

	private void SpawnArrow(Vector2 givenPos, int index)
	{
		calcPos = Globals.GetSafeLinecastVector(givenPos, (index % 2 != 0) ? (-perpendVec) : perpendVec, UnityEngine.Random.Range(0.2f, 0.3f) * (float)(maxSpawnCount - index), ChaosCollisions.layerAllWallAndObst);
		calcDelay = (float)index * 0.1f + 0.05f;
		curArrow = WindArcherChargedArrow.Create(parent, calcPos, parent.skillCategory, skillID, 1, inputVector, 40f, 0.3f, 4, calcDelay);
		curArrow.wallCollider.offset = Vector2.zero;
		curArrow.transform.localScale = Globals.ScaleVec0p75;
		SectionedTrailEmitter poolItem = PoolManager.GetPoolItem<SectionedTrailEmitter>("WindTrail");
		Vector2 startPos = calcPos - inputVector * 2f;
		Vector2 endPos = calcPos + inputVector * 2f;
		float startLifetime = calcDelay + 0.25f;
		poolItem.Emit(startPos, endPos, -1, emitEveryOther: false, -1f, snapToFit: true, startLifetime);
	}
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

[AddComponentMenu("Chaos/Components/Attack")]
public class Attack : ComponentBase
{
	public delegate void AttackCollisionEventHandler(Collider2D col);

	public delegate void EntityCollisionEventHandler(Entity entity);

	public delegate void CritEventHandler(AttackInfo attackInfo, Entity atkEntity = null, Entity hurtEntity = null);

	public static SyncedNumVarStat _camShakeMultiplier;

	private static GameObject circlePrefab;

	private static GameObject boxPrefab;

	public AttackInfo atkInfo;

	public StatData statData;

	public Collider2D collider;

	[HideInInspector]
	public string attackerName;

	private int _attackerObjID;

	public AttackCollisionEventHandler attackCollisionEventHandlers;

	public EntityCollisionEventHandler entityCollisionEventHandlers;

	public static CritEventHandler globalCritEventHandlers;

	public static Dictionary<string, FixedSizeQueue<AttackInfo>> attackHistory;

	private const int attackHistoryQueueSize = 15;

	[HideInInspector]
	public List<int> ignoreTargetsList = new List<int>();

	public Vector2 knockbackOverwriteVector;

	public Vector2 attackerPosOffet;

	[HideInInspector]
	public bool disableKnockbackOverwrite;

	[HideInInspector]
	public int damageOverride = -1;

	[HideInInspector]
	public float damageModifier = 1f;

	private bool damageModifierApplied;

	[HideInInspector]
	public float knockbackMultiplierOverride = -1f;

	private AttackInfo onHitAtkInfo;

	private const float defaultEvadeImmuneTime = 0.5f;

	private Health targetHealth;

	private float sameTargetTimeVal;

	private float sameAttackTimeVal;

	private float timeDiff;

	private FixedSizeQueue<AttackInfo> atkHistQueue;

	private AttackInfo atkHistInfo;

	private AttackInfo generatedAtkInfo;

	private Entity generatedEntity;

	private Vector2 calcKnockbackVector;

	private string checkColObjNameStr;

	public static SyncedNumVarStat CamShakeMultiplier
	{
		get
		{
			if (_camShakeMultiplier == null)
			{
				_camShakeMultiplier = new SyncedNumVarStat(0.02f);
				_camShakeMultiplier.Initialize(0.02f);
			}
			return _camShakeMultiplier;
		}
	}

	public static GameObject CirclePrefab => circlePrefab ?? (circlePrefab = ChaosBundle.Get("Assets/Prefabs/AttackCircle.prefab"));

	public static GameObject BoxPrefab => boxPrefab ?? (boxPrefab = ChaosBundle.Get("Assets/Prefabs/AttackBox.prefab"));

	public int AttackerObjID
	{
		get
		{
			if (_attackerObjID == 0)
			{
				_attackerObjID = gameObject.GetInstanceID();
			}
			return _attackerObjID;
		}
		set
		{
			_attackerObjID = value;
		}
	}

	private void Awake()
	{
		collider = GetComponent<Collider2D>();
		attackerName = ((!(transform.parent == null)) ? (transform.parent.gameObject.name + transform.parent.gameObject.GetInstanceID()) : (gameObject.name + gameObject.GetInstanceID()));
		if (attackHistory == null)
		{
			attackHistory = new Dictionary<string, FixedSizeQueue<AttackInfo>>();
		}
		knockbackOverwriteVector = Vector2.zero;
		attackerPosOffet = Vector2.zero;
		disableKnockbackOverwrite = false;
	}

	public void AnnounceCollisionEvent(Collider2D col, Entity ent)
	{
		if (attackCollisionEventHandlers != null)
		{
			attackCollisionEventHandlers(col);
		}
		if (entityCollisionEventHandlers != null)
		{
			entityCollisionEventHandlers(ent);
		}
	}

	private bool IsSkillOriginator(GameObject other)
	{
		return other != null && other.transform.parent != null && (other.transform.parent.gameObject == parentObject || other.transform.parent.gameObject.name.Contains(atkInfo.skillCategory));
	}

	private bool IsAllyCheck(string attackName, string targetName)
	{
		return !GameController.pvpOn && attackName.StartsWith("Player") && targetName.StartsWith("Ally");
	}

	public void ExecuteAttack(Collider2D col)
	{
		targetHealth = col.gameObject.GetComponent<Health>() ?? col.transform.parent.gameObject.GetComponent<Health>();
		if (targetHealth == null)
		{
			return;
		}
		onHitAtkInfo = new AttackInfo(atkInfo);
		onHitAtkInfo.time = Time.time;
		onHitAtkInfo.targetObjID = col.gameObject.GetInstanceID();
		onHitAtkInfo.attackerPosition = transform.position;
		onHitAtkInfo.targetPosition = col.transform.position;
		if (targetHealth.passThroughAttack)
		{
			targetHealth.TakeDamage(onHitAtkInfo, onHitAtkInfo.entity, critPreCalculated: true);
			return;
		}
		if (Random.value < targetHealth.evadeStat.CurrentValue)
		{
			EvadeAttack(onHitAtkInfo, col);
			return;
		}
		if (!damageModifierApplied && onHitAtkInfo.damage > 0)
		{
			damageModifierApplied = true;
			onHitAtkInfo.damage = Mathf.Max(1, Mathf.FloorToInt((float)onHitAtkInfo.damage * damageModifier));
		}
		if (damageOverride > -1)
		{
			onHitAtkInfo.damage = damageOverride;
		}
		if (damageOverride == 0)
		{
			onHitAtkInfo.canHitStun = false;
			onHitAtkInfo.showDamageEffect = false;
			onHitAtkInfo.showDamageNumber = false;
		}
		onHitAtkInfo.attackingVector = (col.transform.position - transform.position).normalized;
		onHitAtkInfo.knockbackVector = GetKnockbackVector(col.transform.position, transform.position, onHitAtkInfo.knockbackMultiplier, onHitAtkInfo.knockbackOverwrite, attackerPosOffet);
		if (onHitAtkInfo.shakeCamera)
		{
			CameraController.ShakeCamera(Mathf.Min((float)onHitAtkInfo.damage * CamShakeMultiplier.CurrentValue, 2f));
		}
		AnnounceCollisionEvent(col, targetHealth.entityScript);
		if (!targetHealth.invulnerable && Random.value < onHitAtkInfo.critHitChance)
		{
			if (targetHealth.evadeCrit)
			{
				EvadeAttack(onHitAtkInfo, col);
				return;
			}
			if (globalCritEventHandlers != null)
			{
				globalCritEventHandlers(onHitAtkInfo, onHitAtkInfo.entity, targetHealth.entityScript);
			}
			onHitAtkInfo.isCritical = true;
			onHitAtkInfo.damage = Mathf.FloorToInt(onHitAtkInfo.critDmgModifier * (float)onHitAtkInfo.damage);
		}
		if (onHitAtkInfo.isUltimate)
		{
			onHitAtkInfo.damage = Mathf.FloorToInt(onHitAtkInfo.odDmgModifier * (float)onHitAtkInfo.damage);
		}
		if (onHitAtkInfo.isDamageOverride)
		{
			onHitAtkInfo.damage = atkInfo.damage;
		}
		targetHealth.TakeDamage(onHitAtkInfo, onHitAtkInfo.entity, critPreCalculated: true);
		UpdateAttackHistory(onHitAtkInfo.attackInfoKey, onHitAtkInfo);
	}

	public void OnTriggerEnter2D(Collider2D col)
	{
		if (atkInfo != null && CheckCollision(col, col.gameObject.GetInstanceID()))
		{
			ExecuteAttack(col);
		}
	}

	public void UpdateAttackHistory(string givenKey, AttackInfo givenAtkInfo)
	{
		if (!attackHistory.ContainsKey(givenKey))
		{
			attackHistory[givenKey] = new FixedSizeQueue<AttackInfo>(15);
		}
		attackHistory[givenKey].Enqueue(givenAtkInfo);
	}

	public bool CheckAttackHistory(int targetObjID)
	{
		if (!attackHistory.ContainsKey(atkInfo.attackInfoKey))
		{
			return true;
		}
		sameTargetTimeVal = atkInfo.sameTargetImmunityTime;
		sameAttackTimeVal = atkInfo.sameAttackImmunityTime;
		atkHistQueue = attackHistory[atkInfo.attackInfoKey];
		if (sameTargetTimeVal > 0f)
		{
			if (sameAttackTimeVal > 0f)
			{
				for (int num = 14; num >= 0; num--)
				{
					atkHistInfo = atkHistQueue.GetAtIndex(num);
					if (atkHistInfo != null && atkHistInfo.targetObjID == targetObjID)
					{
						timeDiff = Time.time - atkHistInfo.time;
						if (sameTargetTimeVal > timeDiff || (sameAttackTimeVal > timeDiff && atkHistInfo.atkObjID == AttackerObjID))
						{
							return false;
						}
					}
				}
			}
			else
			{
				for (int num2 = 14; num2 >= 0; num2--)
				{
					atkHistInfo = atkHistQueue.GetAtIndex(num2);
					if (atkHistInfo != null && atkHistInfo.targetObjID == targetObjID && sameTargetTimeVal > Time.time - atkHistInfo.time)
					{
						return false;
					}
				}
			}
		}
		else if (sameAttackTimeVal > 0f)
		{
			for (int num3 = 14; num3 >= 0; num3--)
			{
				atkHistInfo = atkHistQueue.GetAtIndex(num3);
				if (atkHistInfo != null && atkHistInfo.targetObjID == targetObjID && sameAttackTimeVal > Time.time - atkHistInfo.time && atkHistInfo.atkObjID == AttackerObjID)
				{
					return false;
				}
			}
		}
		return true;
	}

	public AttackInfo GenerateAttackInfo(StatData curStatData, int skillLevel, bool isUltimate)
	{
		if (curStatData == null)
		{
			return null;
		}
		if (curStatData.category.Contains("Player"))
		{
			if (curStatData.category.EndsWith("0"))
			{
				generatedEntity = GameController.playerScripts[0];
			}
			else if (curStatData.category.EndsWith("1"))
			{
				generatedEntity = GameController.playerScripts[1];
			}
		}
		else
		{
			generatedEntity = entityScript;
		}
		generatedAtkInfo = AttackInfo.GetInfoFromData(generatedEntity, curStatData, skillLevel, isUltimate);
		generatedAtkInfo.knockbackOverwrite = !disableKnockbackOverwrite && generatedAtkInfo.knockbackOverwrite;
		generatedAtkInfo.attacker = attackerName;
		generatedAtkInfo.atkObjID = AttackerObjID;
		if (entityScript != null)
		{
			generatedAtkInfo.gameObject = entityScript.gameObject;
		}
		else if (transform.parent != null)
		{
			generatedAtkInfo.gameObject = transform.parent.gameObject;
		}
		else
		{
			generatedAtkInfo.gameObject = gameObject;
		}
		return generatedAtkInfo;
	}

	public void EvadeAttack(AttackInfo givenInfo, Collider2D givenCol)
	{
		OverheadNumberPool.DisplayOverheadNumber(TextManager.GetUIText("combat-evade"), givenCol.transform.position, (!givenInfo.skillCategory.Contains("Player")) ? Globals.evadeColor : Globals.evadeEnemyColor, OverheadNumber.defaultBorderColor, givenCol.transform.position, givenCol.transform, 0.5f);
		givenInfo.sameAttackImmunityTime = 0.5f;
		UpdateAttackHistory(givenInfo.attackInfoKey, givenInfo);
		if (targetHealth != null)
		{
			targetHealth.AnnounceEvadeEvent();
		}
		SoundManager.PlayWithDistAndSPR("ImpactEvade", transform.position);
	}

	public Vector2 GetKnockbackVector(Vector2 targetPos, Vector2 attackerPos, float kbMultiplier, bool kbOverwrite, Vector2 atkOffset = default(Vector2))
	{
		if (knockbackMultiplierOverride >= 0f)
		{
			kbMultiplier = knockbackMultiplierOverride;
		}
		if (kbMultiplier == 0f)
		{
			return Vector2.zero;
		}
		if (kbOverwrite)
		{
			return knockbackOverwriteVector.normalized * kbMultiplier;
		}
		calcKnockbackVector = targetPos - attackerPos + atkOffset;
		return calcKnockbackVector.normalized * kbMultiplier;
	}

	public bool CheckCollision(Collider2D col, int targetObjID)
	{
		if (atkInfo == null || col == null)
		{
			return false;
		}
		checkColObjNameStr = col.gameObject.name;
		if (IsAllyCheck(atkInfo.skillCategory, checkColObjNameStr) || IsSkillOriginator(col.gameObject) || ignoreTargetsList.Contains(targetObjID))
		{
			return false;
		}
		return isActiveAndEnabled && CheckAttackHistory(targetObjID) && atkInfo.targetNames.Contains(checkColObjNameStr);
	}

	public AttackInfo SetAttackInfo(string newSkillCat, string newSkillID, int newSkillLevel = 1, bool newIsUltimate = false)
	{
		statData = StatManager.GetSkillData(newSkillCat, newSkillID);
		atkInfo = GenerateAttackInfo(statData, newSkillLevel, newIsUltimate);
		return atkInfo;
	}

	public void SetAttackInfo(AttackInfo newAtkInfo, int givenLevel = -1)
	{
		statData = StatManager.GetSkillData(newAtkInfo.skillCategory, newAtkInfo.skillID);
		atkInfo = new AttackInfo(newAtkInfo);
		if (givenLevel > -1)
		{
			ChangeAttackInfoLevel(givenLevel);
		}
	}

	public AttackInfo ChangeAttackInfoLevel(int level)
	{
		return (atkInfo != null) ? SetAttackInfo(atkInfo.skillCategory, atkInfo.skillID, level, atkInfo.isUltimate) : null;
	}

	public AttackInfo GetAtkInfoAtLevel(int givenLevel)
	{
		return (statData != null && atkInfo != null) ? GenerateAttackInfo(statData, givenLevel, atkInfo.isUltimate) : null;
	}

	private void OnDestroy()
	{
		if (atkInfo != null)
		{
			Health.atkObjIDDict.Remove(atkInfo.atkObjID);
		}
	}

	public void EnableForOneFrame(bool destroyOnDisable = false, bool enableComponent = false)
	{
		StartCoroutine(HandleEnableForOneFrame(destroyOnDisable, enableComponent));
	}

	private IEnumerator HandleEnableForOneFrame(bool destroyOnDisable = false, bool enableComponent = false)
	{
		if (enableComponent)
		{
			enabled = true;
		}
		collider.enabled = true;
		yield return new WaitForFixedUpdate();
		if (Time.inFixedTimeStep)
		{
			yield return new WaitForFixedUpdate();
		}
		collider.enabled = false;
		if (destroyOnDisable)
		{
			Object.Destroy(gameObject);
		}
	}
}

