	public override float GetElementalDamageModifier(ElementType damageType)
	{
		if (parentHealth == null || damageType == ElementType.Neutral)
		{
			return 1f;
		}
		eleDmgMulti = 0;
		if (entityElement == damageType)
		{
			eleDmgMulti = -2;
		}
		else if (Health.eleWheelDict.ContainsKey(entityElement) && Health.eleWheelDict[entityElement] == damageType)
		{
			eleDmgMulti = 2;
		}
		else if (Health.eleWheelDict.ContainsKey(damageType) && Health.eleWheelDict[damageType] == entityElement)
		{
			eleDmgMulti = -1;
		}
		return 1f + (float)eleDmgMulti * Health.baseEleBoostValue;
	}

	public override bool TakeDamage(AttackInfo givenAttackInfo, Entity attackEntity, bool preCalc)
	{
		base.TakeDamage(givenAttackInfo, attackEntity, preCalc);
