			attackEntity = currentAtkInfo.entity;
		}
		currentTransform = ((!useHurtBoxTransform || !(entityScript != null)) ? transform : entityScript.hurtBoxTransform);
		if (currentTransform == null)
		{
			return false;
		}
		currentPosition = currentTransform.position;
		if (!currentAtkInfo.isCritical && attackEntity != null && attackEntity is Player)
		{
			currentAtkInfo.isCritical = DoctorPlacebo.placeboStatus[(attackEntity as Player).playerID];
		}
		AnnounceTakeDamageEnter(currentAtkInfo, attackEntity);
		if (!guardNextAtk)
		{
			currentAtkInfo.hitStunDurationModifier *= hitStunModifierStat.CurrentValue;
			currentAtkInfo.knockbackVector *= knockbackModifierStat.CurrentValue;
			currentAtkInfo.knockbackMultiplier *= knockbackModifierStat.CurrentValue;
			minDmgRequired = currentAtkInfo.damage > 0;
			if (!critPreCalculated && !invulnerable && Random.value < currentAtkInfo.critHitChance)
			{
				if (evadeCrit)
				{
					return false;
				}
				if (Attack.globalCritEventHandlers != null)
				{
					Attack.globalCritEventHandlers(currentAtkInfo, currentAtkInfo.entity, entityScript);
				}
				currentAtkInfo.isCritical = true;
				currentAtkInfo.damage = Mathf.FloorToInt(currentAtkInfo.critDmgModifier * (float)currentAtkInfo.damage);
			}
			currentAtkInfo.damage = Mathf.CeilToInt((float)currentAtkInfo.damage * globalDamageTakenModifier);
			AnnouncePreShieldEvent(currentAtkInfo, attackEntity);
			currentDmgVal = currentAtkInfo.damage;
			preCalcDmgVal = currentAtkInfo.damage;
			attackShielded = false;
			if (CurrentShieldValue > 0)
			{
				attackShielded = (float)CurrentShieldValue >= currentDmgVal;
				if (!attackShielded)
				{
					currentDmgVal -= CurrentShieldValue;
					CurrentShieldValue = 0;
				}
			}
			if (!attackShielded)
			{
				currentDmgVal *= GetElementalDamageModifier(currentAtkInfo.elementType);
				if (!currentAtkInfo.isStatusEffect)
				{
					currentDmgVal *= damageTakenStat.CurrentValue;
					currentDmgVal *= 1f - Mathf.Clamp01(armorStat.CurrentValue);
				}
				if (elemModDict.ContainsKey(currentAtkInfo.elementType))
				{
					currentDmgVal *= elemModDict[currentAtkInfo.elementType].CurrentValue;
				}
				if (damageCapStat.CurrentValue > 0f && currentDmgVal > damageCapStat.CurrentValue)
				{
					currentDmgVal = damageCapStat.CurrentValue;
				}
				if (minDmgRequired && currentDmgVal <= 0f)
				{
					currentDmgVal = 1f;
				}
			}
			if (!currentAtkInfo.isStatusEffect)
			{
				if (damageTakenStat.HasOverrideMod && minDmgRequired)
				{
					currentDmgVal = damageTakenStat.CurrentValue;
				}
				else if (currentAtkInfo.isDamageOverride)
				{
					currentDmgVal = currentAtkInfo.damage;
				}
			}
			currentAtkInfo.damage = Mathf.CeilToInt(currentDmgVal);
		}
		calcShowDamageNumbers = showDamageNumbers;
		if (!currentAtkInfo.showDamageNumber)
		{
			calcShowDamageNumbers = false;
		}
		if (calcShowDamageNumbers)
		{
			if (invulnerable)
			{
				dmgTextStr = ((!showInvulnerableMsg) ? string.Empty : TextManager.GetUIText("combat-guard"));
				borderColor = OverheadNumber.defaultBorderColor;
				textColor = Color.gray;
				textSizeScale = 0.5f;
				currentAtkInfo.isCritical = false;
			}
			else if (guardNextAtk)
			{
				dmgTextStr = TextManager.GetUIText("combat-guard");
				borderColor = OverheadNumber.defaultBorderColor;
				textColor = Color.white;
				textSizeScale = 0.5f;
				currentAtkInfo.isCritical = false;
			}
			else
			{
				dmgTextStr = currentAtkInfo.damage.ToString();
				borderColor = ((!attackShielded) ? OverheadNumber.defaultBorderColor : shieldedColor);
				textColor = ((!attackShielded && !(playerEntity == null)) ? playerHurtColor : Color.white);
				textSizeScale = 5f * (float)currentAtkInfo.damage / healthStat.ModifiedValue * ((!currentAtkInfo.isCritical) ? 1f : currentAtkInfo.critDmgModifier);
				if ((float)currentAtkInfo.damage > preCalcDmgVal)
				{
					dmgTextStr = dmgTextStr;
					textColor = boostedDmgColor;
					textSizeScale *= 1.1f;
					overHeadIcon = OverheadNumberIcon.DamageUp;
				}
				else if ((float)currentAtkInfo.damage < preCalcDmgVal)
				{
					dmgTextStr = dmgTextStr;
					textColor = reducedDmgColor;
					textSizeScale *= 0.9f;
					overHeadIcon = OverheadNumberIcon.DamageDown;
				}
				else
				{
					overHeadIcon = OverheadNumberIcon.None;
				}
			}
			OverheadNumberPool.DisplayOverheadNumber(dmgTextStr, currentAtkInfo.attackerPosition, textColor, borderColor, currentPosition, currentTransform, textSizeScale, currentAtkInfo.isCritical, overHeadIcon);
		}
		if (passThroughAttack)
		{
			currentAtkInfo.showDamageEffect = false;
		}
		if (currentAtkInfo.showDamageEffect)
		{
			impactAudioID = "ImpactPhysicalLight";
			if (guardNextAtk)
			{
				impactAudioID = "ImpactGuard";
			}
			else if (attackShielded)
			{
				impactAudioID = "ImpactShield";
			}
			else
			{
				switch (currentAtkInfo.subElementType)
				{
				case ElementType.Chaos:
					impactAudioID = "ImpactChaos";
					break;
				case ElementType.Fire:
					impactAudioID = "ImpactFire";
					break;
				case ElementType.Air:
					impactAudioID = "ImpactAir";
					break;
				case ElementType.Earth:
					impactAudioID = "ImpactEarth";
					break;
				case ElementType.Lightning:
					impactAudioID = "ImpactLightning";
					if (!currentAtkInfo.isStatusEffect)
					{
						PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(3, currentPosition);
					}
					break;
				case ElementType.Water:
				{
					impactAudioID = "ImpactWater";
					WaterHitEffect poolItem = PoolManager.GetPoolItem<WaterHitEffect>();
					int? particleCount = 1;
					Vector3? position = currentPosition;
					Vector3? localEulerAngles = Globals.GetRotationVector((currentAtkInfo.attackerPosition - currentPosition).normalized);
					poolItem.EmitSingle(particleCount, position, null, localEulerAngles);
					break;
				}
				case ElementType.Ice:
					impactAudioID = "ImpactIce";
					break;
				case ElementType.Poison:
					impactAudioID = "ImpactPoison";
					break;
				}
			}
			SoundManager.PlayWithDistAndSPR(impactAudioID, currentPosition);
			if (currentAtkInfo.isCritical)
			{
				SoundManager.PlayWithDistAndSPR("ImpactPhysicalHeavy", currentPosition);
			}
			if (!guardNextAtk)
			{
				if (showHitSpark)
				{
					PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle((currentAtkInfo.damage > 49) ? HitSparkType.Large : ((currentAtkInfo.damage > 24) ? HitSparkType.Medium : HitSparkType.Small), currentAtkInfo.attackerPosition, currentPosition, (!(playerEntity == null)) ? playerHitSparkPSysOverride : null);
				}
				if (!attackShielded && flashRedOnHit)
				{
					StartCoroutine(FlashRed());
					if (playerEntity != null)
					{
						CameraController.cameraHurtEffect.FlashRed(playerEntity.playerID, 1f - Mathf.Clamp((float)currentAtkInfo.damage / healthStat.ModifiedValue * 5.5f, 0.525f, 1f));
					}
				}
			}
		}
		AnnounceTakeDamageEvent(currentAtkInfo, attackEntity);
		lastAttack = currentAtkInfo;
		if (invulnerable)
		{
			return false;
		}
		if (guardNextAtk)
		{
			guardNextAtk = false;
			AnnounceGuardEvent(currentAtkInfo);
			return false;
		}
		if (attackShielded)
		{
			CurrentShieldValue -= currentAtkInfo.damage;
			if (currentAtkInfo.canHitStun)
			{
				AnnounceShieldEvent(currentAtkInfo);
			}
			return false;
		}
		if (CurrentHealthValue < currentAtkInfo.damage)
		{
			currentAtkInfo.damage = CurrentHealthValue;
		}
		CurrentHealthValue -= currentAtkInfo.damage;
		if (CurrentHealthValue <= 0 && deathProof.CurrentValue)
		{
			CurrentHealthValue = 1;
		}
		AnnounceTakeDamageActual(currentAtkInfo, attackEntity);
		HandleOverdriveProgress(currentAtkInfo);
		if (!ignorePlayerEndStats)
		{
			if (enemyEntity != null && attackEntity != null && attackEntity is Player)
			{
				(attackEntity as Player).stats.ModifyValue((!currentAtkInfo.skillID.Contains("Basic")) ? PlayerEndStats.Stat.Spell : PlayerEndStats.Stat.Basic, currentAtkInfo.damage);
			}
			else if (playerEntity != null && currentAtkInfo.skillCategory.Contains("Enemy"))
			{
				playerEntity.stats.ModifyValue(PlayerEndStats.Stat.Taken, currentAtkInfo.damage);
			}
		}
		if (entityScript != null && parentFSM != null)
		{
			if (CurrentHealthValue <= 0 && parentFSM.HasState("Dead"))
			{
				parentFSM.QueueChangeState("Dead");
				AnnounceDeathEvent(entityScript);

				AnnounceDeathEvent(entityScript);
				return true;
			}
			if (faceHurtDirection && currentAtkInfo.canHitStun && currentAtkInfo.showDamageEffect)
			{
				SetHurtDirection(currentAtkInfo);
			}
			statusElementType = ElementType.Neutral;
			if (entityScript.dotManager != null)
			{
				entityElement = entityScript.element;
				switch (currentAtkInfo.elementType)
				{
				case ElementType.Chaos:
					HandleChaosStatusEffect(currentAtkInfo, attackEntity);
					break;
				case ElementType.Fire:
					if (HandleFireStatusEffect(currentAtkInfo, attackEntity))
					{
						statusElementType = ElementType.Fire;
					}
					break;
				case ElementType.Air:
					if (HandleAirStatusEffect(currentAtkInfo, attackEntity))
					{
						statusElementType = ElementType.Air;
					}
					break;
				case ElementType.Earth:
					if (HandleEarthStatusEffect(currentAtkInfo, attackEntity))
					{
						statusElementType = ElementType.Earth;
					}
					break;
				case ElementType.Lightning:
					if (HandleLightningStatusEffect(currentAtkInfo, attackEntity))
					{
						statusElementType = ElementType.Lightning;
					}
					break;
				case ElementType.Water:
					if (HandleWaterStatusEffect(currentAtkInfo, lastAttackEnd))
					{
						statusElementType = ElementType.Water;
					}
					break;
				}
				if (statusElementType != ElementType.Water)
				{
					if (currentAtkInfo.elementType != ElementType.Water && HandleWaterStatusEffect(currentAtkInfo, lastAttackEnd))
					{
						statusElementType = ElementType.Water;
					}
					else if (currentAtkInfo.elementType != ElementType.Lightning && HandleLightningStatusEffect(currentAtkInfo, attackEntity))
					{
						statusElementType = ElementType.Lightning;
					}
					else if (currentAtkInfo.elementType != ElementType.Fire && HandleFireStatusEffect(currentAtkInfo, attackEntity))
					{
						statusElementType = ElementType.Fire;
					}
					else if (currentAtkInfo.elementType != ElementType.Earth && HandleEarthStatusEffect(currentAtkInfo, attackEntity))
					{
						statusElementType = ElementType.Earth;
					}
					else if (currentAtkInfo.elementType != ElementType.Air && HandleAirStatusEffect(currentAtkInfo, attackEntity))
					{
						statusElementType = ElementType.Air;
					}
					if (statusElementType != ElementType.Neutral && statusElementType != currentAtkInfo.elementType)
					{
						ElementalStatusEffect component = Object.Instantiate(ElementalStatusEffect.Prefab, entityScript.hurtBoxTransform.position, Quaternion.identity).GetComponent<ElementalStatusEffect>();
						component.followTrans = entityScript.hurtBoxTransform;
						component.element = statusElementType;
					}
					HandleRootStatusEffect(currentAtkInfo, attackEntity);
				}
				if (statusElementType != ElementType.Neutral && globalDoTEventHandlers != null)
				{
					globalDoTEventHandlers(currentAtkInfo, statusElementType, attackEntity, entityScript);
				}
			}
			lastAttackEnd = currentAtkInfo;
			if (statusElementType == ElementType.Water)
			{
				return false;
			}
			if (!IgnoreHurtState && currentAtkInfo.canHitStun && parentFSM.HasState("Hurt") && !parentFSM.currentStateName.Contains("Fall"))
			{
				if (!ignoreHitStunDurationModifier)
				{
					entityScript.hitStunDurationModifier = currentAtkInfo.hitStunDurationModifier;
				}
				parentFSM.ChangeState("Hurt");
				return false;
			}
			if (parentFSM.currentStateName.Contains("Frozen"))
			{
				parentFSM.QueueChangeState(parentFSM.defaultStateName);
				return false;
			}
		}
		return false;
	}

