	public bool CheckFreezeChance(AttackInfo curAtk, AttackInfo lastAtk)
	{
		if (ignoreFreeze.CurrentValue || lastAttack.freezeChance <= 0f || !parentFSM.HasState("Frozen") || entityElement == ElementType.Water)
		{
			return false;
		}
		if (enemyEntity != null && parentFSM.currentStateName.Contains("Frozen") && curAtk.freezeChance > 0f && lastAtk != null && curAtk.attackInfoKey == lastAtk.attackInfoKey)
		{
			return !curAtk.skillID.Contains("Basic") || curAtk.skillLevel != 1;
		}
		return Random.value < lastAttack.freezeChance * statusResDict[ElementType.Water].CurrentValue;
	}

