	private IEnumerator SetInvulnerable(float duration, bool showMsg)
	{
		if (invulnerableCoroutineActive)
		{
			ChaosStopwatch.Refresh(invulnerabilityStopwatchID, duration);
			yield break;
		}
		invulnerableCoroutineActive = true;
		bool originalInvulStatus = invulnerable;
		bool originalInvulMsgStatus = showInvulnerableMsg;
		invulnerable = true;
		showInvulnerableMsg = showMsg;
		invulnerabilityStopwatchID = ChaosStopwatch.Begin(duration);
		while (!ChaosStopwatch.Check(invulnerabilityStopwatchID))
		{
			yield return null;
		}
		invulnerable = originalInvulStatus;
		showInvulnerableMsg = originalInvulMsgStatus;
		invulnerableCoroutineActive = false;
	}

	public IEnumerator FlashRed()
	{
		if (entitySprites.Count == 0)
		{
			yield break;
		}
		for (int i = 0; i < entitySprites.Count; i++)
		{
			if (!(entitySprites[i] == null))
			{
				if (entitySprites[i].name.Contains("Player"))
				{
					entitySprites[i].material.SetVector("_FlashColor", new Vector4(0.6f, 0.1f, 0.1f, 1f));
				}
				entitySprites[i].material.SetFloat("_FlashAmount", 1f);
			}
		}
		yield return waitForFlashDelay;
		for (int j = 0; j < entitySprites.Count; j++)
		{
			if (!(entitySprites[j] == null))
			{
				entitySprites[j].material.SetFloat("_FlashAmount", 0f);
			}
		}
		entitySprites = entitySprites.Where((SpriteRenderer y) => y != null).ToList();
	}

	public IEnumerator RegenHealth(float healAmount, float regenRate = 20f, float timePerTick = 0.2f, float initialHealAmount = 0f)
	{
		float totalRegenAmount = healAmount;
		float healthPerTick = regenRate * timePerTick;
		bool healthPerTickIsInt = true;
		bool roundedUp = true;
		int tickStopwatchID = -1;
		if (initialHealAmount > 0f)
		{
			RestoreHealth((int)initialHealAmount);
			tickStopwatchID = ChaosStopwatch.Begin(timePerTick);
		}
		if (healthPerTick != Mathf.Ceil(healthPerTick))
		{
			healthPerTickIsInt = false;
		}
		while (totalRegenAmount > 0f)
		{
			if ((float)CurrentHealthValue >= healthStat.ModifiedValue || CurrentHealthValue <= 0)
			{
				totalRegenAmount = 0f;
				break;
			}
			if (ChaosStopwatch.Check(tickStopwatchID))
			{
				tickStopwatchID = ChaosStopwatch.Begin(timePerTick);
				if (!healthPerTickIsInt)
				{
					int roundedHealPerTick;
					if (roundedUp)
					{
						roundedHealPerTick = Mathf.CeilToInt(healthPerTick);
						roundedUp = false;
					}
					else
					{
						roundedHealPerTick = Mathf.FloorToInt(healthPerTick);
						roundedUp = true;
					}
					if ((float)roundedHealPerTick > totalRegenAmount)
					{
						roundedHealPerTick = (int)totalRegenAmount;
					}
					RestoreHealth(roundedHealPerTick);
					totalRegenAmount -= (float)roundedHealPerTick;
				}
				else
				{
					RestoreHealth((int)healthPerTick);
					totalRegenAmount -= healthPerTick;
				}
			}
			yield return null;
		}
	}

	public void ToggleIgnoreHurt(BoolVarStatMod givenMod, bool givenStatus = true)
	{
		ignoreHurtVarStat.Modify(givenMod, givenStatus);
		faceHurtDirection = !ignoreHurtVarStat.CurrentValue;
	}
}

using UnityEngine;

public class DoTEffect
{
	public int skillLevel;

	public StatData statData;

	public int damageStopwatchID;

	public float damageInterval;

	public bool useInterval = true;

	public int hitCount;

	public string ID;

	public string category;

	public AttackInfo atkInfo;

	public bool applyInstantly;

	public Entity parentEntity;

	public Entity attackEntity;

	public bool isBuff;

	private bool firstHit;

	private bool baseShowDamageEffect;

	public string sfxName = string.Empty;

	public bool randomFacingDir;

	public ElementType dotElement = ElementType.Neutral;

	public DoTEffect(string skillCat, string skillID, int newSkillLevel, Entity hurtEntity, Entity attackerEntity, bool instant = true)
	{
		ID = skillID;
		category = skillCat;
		statData = StatManager.GetSkillData(category, ID);
		skillLevel = newSkillLevel;
		parentEntity = hurtEntity;
		attackEntity = attackerEntity;
		applyInstantly = instant;
	}

	public virtual bool Update()
	{
		if (atkInfo == null || parentEntity == null || parentEntity.health == null || parentEntity.health.healthStat.CurrentValue <= 0f)
		{
			CleanUp();
			return true;
		}
		switch (ChaosStopwatch.CheckInterval(damageStopwatchID))
		{
		case StopwatchState.Running:
			return false;
		case StopwatchState.Ready:
			atkInfo.showDamageEffect = baseShowDamageEffect && (!firstHit || !applyInstantly);
			firstHit = false;
			atkInfo.attackerPosition = parentEntity.hurtBoxTransform.position;
			if (randomFacingDir)
			{
				atkInfo.attackerPosition = Random.insideUnitCircle;
				atkInfo.knockbackVector = -atkInfo.attackerPosition * atkInfo.knockbackMultiplier;
			}
			parentEntity.health.TakeDamage(atkInfo, attackEntity, critPreCalculated: true);
			if (sfxName != string.Empty)
			{
				SoundManager.PlayAudioWithDistance(sfxName, parentEntity.transform.position);
			}
			OnDamageTick();
			return false;
		case StopwatchState.Done:
			CleanUp();
			return true;
		default:
			return true;
		}
	}

	public virtual void Init()
	{
		InitDotVars();
	}

	public virtual void InitDotVars()
	{
		if (statData != null)
		{
			firstHit = true;
			skillLevel = Mathf.Clamp(skillLevel, 1, 5);
			atkInfo = AttackInfo.GetInfoFromData(attackEntity, statData, skillLevel, givenUlt: false);
			baseShowDamageEffect = atkInfo.showDamageEffect;
			damageInterval = statData.GetValue<float>(StatData.intervalStr, skillLevel);
			hitCount = (int)(statData.GetValue<float>(StatData.durStr, skillLevel) / damageInterval);
			damageStopwatchID = ChaosStopwatch.Begin((!applyInstantly) ? damageInterval : 0f, useInterval, damageInterval, hitCount);
		}
	}

	public virtual void CleanUp()
	{
	}

	public virtual void Refresh(int hits = 0, float time = 0f)
	{
		if (useInterval)
		{
			int num = ((hits != 0) ? hits : hitCount);
			if (ChaosStopwatch.GetRemainingIntervals(damageStopwatchID) < num)
			{
				ChaosStopwatch.RefreshIntervals(damageStopwatchID, num);
			}
		}
		else
		{
			ChaosStopwatch.Refresh(damageStopwatchID, (time != 0f) ? time : damageInterval);
		}
	}

	public virtual void Stop()
	{
		ChaosStopwatch.Stop(damageStopwatchID);
	}

	public virtual void OnDamageTick()
	{
	}
}
using System.Collections.Generic;

public class DoTManager
{
	private Entity entity;

	public Dictionary<string, DoTEffect> dotDict;

	private List<string> dotIDList;

	public int ActiveDotCount => dotDict.Values.Count;

	public DoTManager(Entity newEntity)
	{
		dotDict = new Dictionary<string, DoTEffect>();
		dotIDList = new List<string>();
		entity = newEntity;
	}

	public void Update()
	{
		if (dotDict.Count == 0)
		{
			return;
		}
		dotIDList.AddRange(dotDict.Keys);
		for (int num = dotIDList.Count - 1; num >= 0; num--)
		{
			if (!DotIsActive(dotIDList[num]))
			{
				AnnounceStatusEvent(dotDict[dotIDList[num]], givenStatus: false);
				dotDict.Remove(dotIDList[num]);
			}
		}
		dotIDList.Clear();
	}

	public bool HasDot(string dotID)
	{
		return dotDict.ContainsKey(dotID) && dotDict[dotID] != null;
	}

	public bool DotIsActive(string givenID)
	{
		return HasDot(givenID) && !dotDict[givenID].Update();
	}

	public void AddDot(DoTEffect newDot)
	{
		if (HasDot(newDot.ID))
		{
			if (dotDict[newDot.ID].skillLevel <= newDot.skillLevel)
			{
				dotDict[newDot.ID].skillLevel = newDot.skillLevel;
				dotDict[newDot.ID].InitDotVars();
				dotDict[newDot.ID].Refresh(newDot.hitCount, newDot.damageInterval);
				AnnounceStatusEvent(newDot, givenStatus: true);
			}
		}
		else
		{
			dotDict[newDot.ID] = newDot;
			newDot.Init();
			AnnounceStatusEvent(newDot, givenStatus: true);
		}
	}

	public void RemoveDot(string givenID)
	{
		if (HasDot(givenID))
		{
			dotDict[givenID].Stop();
		}
	}

	public void ApplyStopElement(ElementType givenElement)
	{
		switch (givenElement)
		{
		case ElementType.Fire:
			RemoveDot(SlowDotEffect.slowStatusStr);
			break;
		case ElementType.Air:
			RemoveDot(PoisonDotEffect.poisonStatusStr);
			break;
		case ElementType.Earth:
			RemoveDot(ShockDotEffect.shockStatusStr);
			break;
		case ElementType.Lightning:
			if (entity != null && entity.fsm != null && entity.fsm.currentStateName == "Frozen")
			{
				entity.fsm.QueueChangeState(entity.fsm.defaultStateName);
			}
			break;
		case ElementType.Water:
			RemoveDot(BurnDoTEffect.burnStatusStr);
			break;
		case ElementType.Chaos:
			RemoveDot(BurnDoTEffect.burnStatusStr);
			RemoveDot(SlowDotEffect.slowStatusStr);
			RemoveDot(PoisonDotEffect.poisonStatusStr);
			RemoveDot(ShockDotEffect.shockStatusStr);
			if (entity != null && entity.fsm != null && entity.fsm.currentStateName == "Frozen")
			{
				entity.fsm.QueueChangeState(entity.fsm.defaultStateName);
			}
			break;
		case ElementType.Neutral:
			break;
		}
	}

	public void RemoveAll(bool keepBuffs = true)
	{
		List<DoTEffect> list = new List<DoTEffect>();
		foreach (DoTEffect value in dotDict.Values)
		{
			if (value != null && (!keepBuffs || !value.isBuff))
			{
				list.Add(value);
			}
		}
		for (int i = 0; i < list.Count; i++)
		{
			list[i].CleanUp();
			RemoveDot(list[i].ID);
		}
	}

	public void AnnounceStatusEvent(DoTEffect givenDot, bool givenStatus)
	{
		if (entity != null && givenDot != null && !givenDot.isBuff)
		{
			entity.AnnounceStatusEffectEvent(givenDot.dotElement, givenStatus);
		}
	}
}
