public class BurnMark : MonoBehaviour
{
	public enum BurnMarkType
	{
		XSmall,
		Small,
		Med,
		Large
	}

	private SpriteRandomizer xSmallSpriteRand;

	private SpriteRandomizer smallSpriteRand;

	private SpriteRandomizer medSpriteRand;

	private SpriteRandomizer largeSpriteRand;

	private SpriteRenderer xSmallSpriteRend;

	private SpriteRenderer smallSpriteRend;

	private SpriteRenderer medSpriteRend;

	private SpriteRenderer largeSpriteRend;

	private SpriteRenderer curSpriteRend;

	private SpriteRandomizer curSpriteRand;

	private SpriteRenderer[] spriteRenderers;

	[HideInInspector]
	public bool visible;

	[HideInInspector]
	public float fadeTime = 3f;

	[HideInInspector]
	public float fadeTimer;

	private Color32 transColor = new Color32(byte.MaxValue, byte.MaxValue, byte.MaxValue, 0);

	private float FadeStartTime => fadeTime * 0.1f;

	private void Update()
	{
		if (!visible)
		{
			return;
		}
		if (fadeTimer <= 0f)
		{
			Deactivate();
			return;
		}
		fadeTimer -= Time.deltaTime;
		if (fadeTimer <= FadeStartTime)
		{
			curSpriteRend.color = new Color(1f, 1f, 1f, Mathf.Lerp(1f, 0f, 1f - fadeTimer / FadeStartTime));
		}
	}

	private void Awake()
	{
		Transform transform = base.transform.Find("BurnMarkLargeSprite");
		largeSpriteRand = transform.GetComponent<SpriteRandomizer>();
		largeSpriteRend = transform.GetComponent<SpriteRenderer>();
		Transform transform2 = base.transform.Find("BurnMarkMedSprite");
		medSpriteRand = transform2.GetComponent<SpriteRandomizer>();
		medSpriteRend = transform2.GetComponent<SpriteRenderer>();
		Transform transform3 = base.transform.Find("BurnMarkSmallSprite");
		smallSpriteRand = transform3.GetComponent<SpriteRandomizer>();
		smallSpriteRend = transform3.GetComponent<SpriteRenderer>();
		Transform transform4 = base.transform.Find("BurnMarkXSmallSprite");
		xSmallSpriteRand = transform4.GetComponent<SpriteRandomizer>();
		xSmallSpriteRend = transform4.GetComponent<SpriteRenderer>();
		spriteRenderers = new SpriteRenderer[4] { xSmallSpriteRend, smallSpriteRend, medSpriteRend, largeSpriteRend };
	}

	public void Activate(Vector3 newPos, BurnMarkType burnMarkType = BurnMarkType.Small, float fadeTime = 3f)
	{
		Deactivate();
		visible = true;
		this.fadeTime = fadeTime;
		switch (burnMarkType)
		{
		case BurnMarkType.XSmall:
			curSpriteRend = xSmallSpriteRend;
			curSpriteRand = xSmallSpriteRand;
			break;
		case BurnMarkType.Small:
			curSpriteRend = smallSpriteRend;
			curSpriteRand = smallSpriteRand;
			break;
		case BurnMarkType.Med:
			curSpriteRend = medSpriteRend;
			curSpriteRand = medSpriteRand;
			break;
		case BurnMarkType.Large:
			curSpriteRend = largeSpriteRend;
			curSpriteRand = largeSpriteRand;
			break;
		}
		curSpriteRand.Randomize();
		curSpriteRend.enabled = true;
		curSpriteRend.color = Color.white;
		fadeTimer = fadeTime;
		transform.position = newPos;
	}

	public void Deactivate()
	{
		visible = false;
		for (int i = 0; i < spriteRenderers.Length; i++)
		{
			spriteRenderers[i].enabled = false;
			spriteRenderers[i].color = transColor;
		}
		fadeTimer = 0f;
	}
}
