		InitField(ref elementType, "Neutral");
		InitField(ref subElementType, elementType[0]);
		InitField(ref showDamageNumber, givenDefault: true);
		InitField(ref showDamageEffect, givenDefault: true);
		InitField(ref shakeCamera, givenDefault: true);
		InitField(ref targetNames, string.Empty, propagate: false);
		InitField(ref sameTargetImmunityTime, 0f);
		InitField(ref sameAttackImmunityTime, 0f);
		InitField(ref canHitStun, givenDefault: true);
		InitField(ref hitStunDurationModifier, 1f);
		InitField(ref knockbackMultiplier, 0f);
		InitField(ref knockbackOverwrite, givenDefault: false);
		InitField(ref damage, 0);
		InitField(ref cooldown, 0f);
		InitField(ref duration, 0f);
		InitField(ref hitCount, 0);
		InitField(ref damageInterval, 0f);
