		InitField(ref baseHealth, 0);
		InitField(ref criticalHitChance, 0.05f);
		InitField(ref criticalDamageModifier, 1.5f);
		InitField(ref isStatusEffect, givenDefault: false);
		InitField(ref rootChance, 0f);
		InitField(ref rootDuration, 2f);
		InitField(ref chaosChance, 0f);
		InitField(ref chaosLevel, 1);
		InitField(ref burnChance, 0f);
