		InitField(ref shockChance, 0f);
		InitField(ref shockLevel, 1);
		InitField(ref freezeChance, 0f);
		InitField(ref freezeDuration, 1.5f);
		InitField(ref overdriveDamageMultiplier, 1f);
		InitField(ref overdriveProgressMultiplier, 1f);
		InitField(ref overdriveSingleIncrease, givenDefault: false);
	}

	private void InitField<T>(ref T[] givenArray, T givenDefault, bool propagate = true)
	{
		if (givenArray == null)
		{
			givenArray = new T[maxSkillLevel];
			for (int i = 0; i < maxSkillLevel; i++)
			{
				givenArray[i] = givenDefault;
			}
			return;
		}
		T[] array = new T[maxSkillLevel];
		for (int j = 0; j < maxSkillLevel; j++)
		{
			ref T reference = ref array[j];
			T val;
			if (j < givenArray.Length && givenArray[j] != null)
			{
				val = givenArray[j];
			}
			else
			{
				val = ((!propagate) ? givenDefault : array[j - 1]);
			}
			reference = val;
		}
		givenArray = array;
	}
}
