public class OutfitModStat
{
	public enum OutfitModType
	{
		None,
		Health,
		Speed,
		Run,
		Evade,
		Armor,
		CritChance,
		CritDamage,
		Damage,
		Cooldown,
		Pride,
		Fall,
		ODRate,
		ODDamage,
		HealAmount,
		HealCrit,
		Gold,
		Platinum,
		AllowUpgrade
	}

	public OutfitModType modType;

	protected string modIDPrefix = "OutfitModifier";

	protected string modifierID = string.Empty;

	protected string statDescription = string.Empty;

	protected string statDataFieldKey = string.Empty;

	protected bool updateValue;

	protected bool isIncrease;

	public bool hasAddValue;

	public NumVarStatMod addModifier;

	public bool hasMultiValue;

	public NumVarStatMod multiModifier;

	public bool hasOverrideValue;

	public NumVarStatMod overrideModifier;

	private BoolVarStatMod boolModifier;

	protected List<NumVarStat> targetNumVarStatList;

	protected List<BoolVarStat> targetBoolVarStatList;

	public OutfitModStat(OutfitModType givenType = OutfitModType.None, float addValue = 0f, float multiValue = 0f, float overrideValue = 0f, bool boolValue = false)
	{
		Initialize(givenType, addValue, multiValue, overrideValue, boolValue);
	}

	public OutfitModStat(OutfitModStat givenOM)
	{
		Initialize(givenOM.modType, givenOM.addModifier.modValue, givenOM.multiModifier.modValue, givenOM.overrideModifier.modValue, givenOM.boolModifier.modValue);
	}

	private void Initialize(OutfitModType givenType, float givenAdd, float givenMulti, float givenOver, bool givenBool)
	{
		modType = givenType;
		SetInitialVars();
		isIncrease = givenAdd + givenMulti > 0f;
		hasAddValue = givenAdd != 0f;
		hasMultiValue = givenMulti != 0f;
		hasOverrideValue = givenOver != 0f;
		addModifier = new NumVarStatMod(modIDPrefix + "Add" + modifierID, givenAdd);
		multiModifier = new NumVarStatMod(modIDPrefix + "Multi" + modifierID, givenMulti, 10, VarStatModType.Multiplicative);
		overrideModifier = new NumVarStatMod(modIDPrefix + "Override" + modifierID, givenOver, 1, VarStatModType.Override);
		targetNumVarStatList = new List<NumVarStat>();
		boolModifier = new BoolVarStatMod(modIDPrefix + "Bool" + modifierID, givenBool);
		targetBoolVarStatList = new List<BoolVarStat>();
	}

	private void SetInitialVars()
	{
		switch (modType)
		{
		case OutfitModType.Health:
			modifierID = "Health";
			statDescription = "wardrobeUI-statHealth";
			updateValue = true;
			break;
