	private void SetTargetVarStatList(Player p)
	{
		if (targetNumVarStatList != null)
		{
			targetNumVarStatList.Clear();
		}
		if (targetBoolVarStatList != null)
		{
			targetBoolVarStatList.Clear();
		}
		switch (modType)
		{
		case OutfitModType.Health:
			targetNumVarStatList.Add(p.health.healthStat);
			return;
		case OutfitModType.Speed:
			targetNumVarStatList.Add(p.movement.moveSpeedStat);
			return;
		case OutfitModType.Run:
			targetNumVarStatList.Add(p.runSpeedupStat);
			return;
		case OutfitModType.Evade:
			targetNumVarStatList.Add(p.health.evadeStat);
			return;
		case OutfitModType.Armor:
			targetNumVarStatList.Add(p.health.armorStat);
			return;
		case OutfitModType.Pride:
			targetNumVarStatList.Add(p.health.shieldStat);
			return;
		case OutfitModType.Fall:
			targetBoolVarStatList.Add(p.healthRegenStat);
			return;
		case OutfitModType.AllowUpgrade:
			targetBoolVarStatList.Add(p.outfitEnhanceAllowStat);
			return;
		case OutfitModType.HealAmount:
			targetNumVarStatList.Add(p.health.healModifierStat);
			return;
		case OutfitModType.HealCrit:
			targetNumVarStatList.Add(p.health.critHealModStat);
			return;
		case OutfitModType.Gold:
			targetNumVarStatList.Add(LootManager.globalGoldModifier);
			return;
		case OutfitModType.Platinum:
			targetNumVarStatList.Add(LootManager.globalPlatModifier);
			return;
		}
		if (!(statDataFieldKey != string.Empty))
		{
			return;
		}
		List<StatData> allStatData = StatManager.GetAllStatData("Skills", p.skillCategory);
		int count = allStatData.Count;
		for (int i = 0; i < count; i++)
		{
			if (!allStatData[i].GetValue<bool>("isStatusEffect"))
			{
				allStatData[i].EnsureVarStatEntry(statDataFieldKey);
				targetNumVarStatList.Add(allStatData[i].numVarStatDict[statDataFieldKey]);
			}
		}
	}

	public virtual void SetModStatus(Player givenPlayer, bool givenStatus, bool allowUpdate = true)
	{
		if (givenPlayer == null)
		{
			return;
		}
		isIncrease = addModifier.modValue + multiModifier.modValue > 0f;
		SetTargetVarStatList(givenPlayer);
		if (targetNumVarStatList != null && targetNumVarStatList.Count > 0)
		{
			int count = targetNumVarStatList.Count;
			if (givenStatus)
			{
				for (int i = 0; i < count; i++)
				{
					NumVarStat numVarStat = targetNumVarStatList[i];
					if (hasAddValue)
					{
						numVarStat.AddMod(addModifier);
					}
					if (hasMultiValue)
					{
						numVarStat.AddMod(multiModifier);
					}
					if (hasOverrideValue)
					{
						numVarStat.AddMod(overrideModifier);
					}
					if (updateValue && allowUpdate)
					{
						numVarStat.CurrentValue = numVarStat.ModifiedValue;
					}
				}
			}
			else
			{
				for (int j = 0; j < count; j++)
				{
					NumVarStat numVarStat = targetNumVarStatList[j];
					if (hasAddValue)
					{
						numVarStat.RemoveMod(addModifier.ID);
					}
					if (hasMultiValue)
					{
						numVarStat.RemoveMod(multiModifier.ID);
					}
					if (hasOverrideValue)
					{
						numVarStat.RemoveMod(overrideModifier.ID);
					}
					if (updateValue && allowUpdate)
					{
						numVarStat.CurrentValue = numVarStat.ModifiedValue;
					}
				}
			}
		}
		if (targetBoolVarStatList != null && targetBoolVarStatList.Count > 0)
		{
			int count = targetBoolVarStatList.Count;
			for (int k = 0; k < count; k++)
			{
				targetBoolVarStatList[k].Modify(boolModifier, givenStatus);
			}
		}
	}

	public virtual string GetDescription(bool addExtra = false)
	{
		return modType switch
		{
			OutfitModType.Platinum => TextManager.GetUIText("wardrobeUI-platinum") + (addExtra ? (" <color=#009999>( </color><color=#00dddd> + " + Mathf.FloorToInt(addModifier.modValue) + " </color><color=#009999> )</color>") : string.Empty), 
			OutfitModType.Gold => TextManager.GetUIText("wardrobeUI-gold") + (addExtra ? (" <color=#009999>( </color><color=#00dddd>" + Globals.PercentToStr(multiModifier, "+") + "</color><color=#009999> )</color>") : string.Empty), 
			OutfitModType.Pride => TextManager.GetUIText("wardrobeUI-statPride"), 
			OutfitModType.Fall => TextManager.GetUIText("wardrobeUI-statFall"), 
			OutfitModType.None => TextManager.GetUIText("wardrobeUI-statNone"), 
			OutfitModType.AllowUpgrade => string.Empty, 
			_ => ((!isIncrease) ? TextManager.GetUIText("wardrobeUI-decreaseStat") : TextManager.GetUIText("wardrobeUI-increaseStat")) + TextManager.GetUIText(statDescription) + ((!addExtra) ? string.Empty : (" <color=#009999>( </color><color=#00dddd>" + (hasAddValue ? Globals.PercentToStr(addModifier, (!isIncrease) ? "-" : "+") : (hasMultiValue ? Globals.PercentToStr(multiModifier, (!isIncrease) ? "-" : "+") : ((!hasOverrideValue) ? string.Empty : ((int)overrideModifier.modValue/*cast due to constrained. prefix*/).ToString()))) + "</color><color=#009999> )</color>")), 
		};
	}
}

