public override void Awake()
{
	if (instance != null && instance != this)
	{
		UnityEngine.Object.Destroy(gameObject);
		return;
	}
	base.Awake();
	instance = this;
	skillsDict = new Dictionary<string, SkillState>();
	playerSummonsList = new List<GameObject>();
	playerSummonsList.Add(gameObject);
	cooldownManager = new CooldownManager();
	multiAnimHurt = true;
	overdriveBuildDecayRate = new SyncedNumVarStat(4.5f);
	overdriveActiveDecayRate = new SyncedNumVarStat(10f);
	curOverdriveDecayRate = overdriveBuildDecayRate;
	UnityEngine.Object.DontDestroyOnLoad(gameObject);
	BoolVarStat boolVarStat = healthRegenStat;
	boolVarStat.statChangedEventHandlers = (VarStat<bool>.StatChangedEventHandler)Delegate.Combine(boolVarStat.statChangedEventHandlers, new VarStat<bool>.StatChangedEventHandler(OnRegenStatChanged));
	if (animStrDict == null)
	{
		LoadAnimStrDict();
	}
}

private void LoadAnimStrDict()
{
	animStrDict = new Dictionary<string, Dictionary<FacingDirection, string>>();
	foreach (string animStr in animStrList)
	{
		animStrDict[animStr] = new Dictionary<FacingDirection, string>();
		animStrDict[animStr][FacingDirection.Neutral] = animStr + "Up";
		animStrDict[animStr][FacingDirection.Up] = animStr + "Up";
		animStrDict[animStr][FacingDirection.Down] = animStr + "Down";
		animStrDict[animStr][FacingDirection.Left] = animStr + "Left";
		animStrDict[animStr][FacingDirection.Right] = animStr + "Right";
	}
}

