private void HandleHealthRegen()
{
	if (!regenEnabled || regenCompleted || IsDead || (float)health.CurrentHealthValue >= health.healthStat.ModifiedValue)
	{
		if (regenEffect != null)
		{
			regenEffect.Stop();
			regenEffect = null;
		}
		return;
	}
	if (!regenStarted)
	{
		regenStarted = true;
		regenStopwatchID = ChaosStopwatch.Begin(regenDelay, useInterval: true, regenInterval, (int)(health.healthStat.ModifiedValue - health.healthStat.CurrentValue));
		regenAudioInterval = 0;
	}
	switch (ChaosStopwatch.CheckInterval(regenStopwatchID))
	{
	case StopwatchState.Ready:
		if (health.HealthPercentage >= 1f)
		{
			ChaosStopwatch.Stop(regenStopwatchID);
			OnRegenCompleted();
		}
		else
		{
			health.healthStat.CurrentValue++;
			regenAudioInterval++;
			if (regenAudioInterval % 5 == 0)
			{
				SoundManager.PlayAudio("HealRegen");
			}
		}
		if (!regenEffectPlayed)
		{
			regenEffectPlayed = true;
			SoundManager.PlayAudio("Heal");
			UnityEngine.Object.Instantiate(HealthPowerup.EffectPrefab, transform.position, Quaternion.identity, transform);
			regenEffect = PoolManager.GetPoolItem<ParticleEffect>("RegenEffect");
			regenEffect.followTransform = transform;
			regenEffect.Play(40f);
		}
		break;
	case StopwatchState.Done:
		OnRegenCompleted();
		break;
	}
}

private void OnRegenCompleted()
{
	if (regenEffect != null)
	{
		regenEffect.Stop();
		regenEffect = null;
	}
	regenCompleted = true;
	SoundManager.PlayAudio("FullHealth");
	UnityEngine.Object.Instantiate(HealthPowerup.EffectPrefab, transform.position, Quaternion.identity, transform);
}

public void StopRegenEvent(AttackInfo info = null, Entity ent = null)
{
	if (regenEnabled)
	{
		regenStarted = false;
