public SkillState GetRandomStandardSkill(bool allowEmp = true, bool allowStd = true)
{
	List<SkillState> list = new List<SkillState>();
	for (int i = 0; i < 6; i++)
	{
		SkillState skillState = assignedSkills[i];
		if (skillState != null && !skillState.isBasic && !skillState.isDash && !skillState.isSignature && ((allowEmp && skillState.IsEmpowered) || (allowStd && !skillState.IsEmpowered)))
		{
			list.Add(skillState);
		}
	}
	if (stockSkill != null)
	{
		SkillState skillState = stockSkill;
		if ((allowEmp && skillState.IsEmpowered) || (allowStd && !skillState.IsEmpowered))
		{
			list.Add(skillState);
		}
	}
	if (list.Count == 0)
	{
		return null;
	}
	return list[UnityEngine.Random.Range(0, list.Count)];
}

