public void InitSkills()
{
	skillIDs = new string[skillsDict.Keys.Count];
	skillStates = new SkillState[skillsDict.Values.Count];
	skillsDict.Keys.CopyTo(skillIDs, 0);
	skillsDict.Values.CopyTo(skillStates, 0);
	foreach (SkillState value in skillsDict.Values)
	{
		value.SetSkillLevel(1);
		value.isUltimate = false;
	}
	assignedSkills = new SkillState[6];
	for (int i = 0; i < assignedSkills.Length; i++)
	{
		string text = playerData.skills[i];
		if (text != null && text != string.Empty && (!skillsDict.ContainsKey(text) || (i == playerData.signatureSkillIndex && !skillsDict[text].hasSignatureVariant)))
		{
			playerData.ResetSkills();
			break;
		}
	}
	if (!Globals.IsMuseum)
	{
		for (int j = 0; j < assignedSkills.Length; j++)
		{
			AssignSkillSlot(j, playerData.skills[j], playerData.signatureSkillIndex == j, signatureStatus: true);
		}
	}
	if (lowerHUD != null && lowerHUD.cooldownUI != null)
	{
		lowerHUD.cooldownUI.RefreshEntries();
	}
}

