public void AssignSkillSlot(int skillSlotNum, string skillID, bool setSignature = false, bool signatureStatus = false)
{
	SkillState skillState = null;
	if (skillID != string.Empty && skillsDict.ContainsKey(skillID))
	{
		skillState = skillsDict[skillID];
	}
	assignedSkills[skillSlotNum] = skillState;
	if (skillState != null)
	{
		if (setSignature)
		{
			skillState.isSignature = signatureStatus;
			skillState.SetEmpowered(signatureStatus, EmpowerStatMods.DefaultEmpowerMod);
		}
		assignedSkills[skillSlotNum].skillSlot = skillSlotNum;
	}
	if (assignSkillSlotEventHandlers != null)
	{
		assignSkillSlotEventHandlers(skillState, skillSlotNum);
	}
	AnnounceSkillChanged(skillState);
	if (skillSlotNum != -1 && skillState != null)
	{
		NewSpellManager.Remove(skillState.skillID, skillState.isSignature);
	}
}

public void PickUpSkill(string givenID, bool isSignature = false, bool isEmpowered = false)
{
	int num = -1;
	if (isSignature)
	{
		isEmpowered = true;
		HandleSkillUnlock(givenID, isSignature: true);
	}
	if (HasSkill(givenID))
	{
		if (!isEmpowered)
		{
			HandleSkillDrop(GetSkill(givenID));
		}
		else
		{
			num = GetSkill(givenID).skillSlot;
		}
	}
	else
	{
		if (skillsDict[givenID].isBasic)
		{
			num = HandleSkillDrop(GetBasicSkill());
		}
		else
		{
			num = ((!skillsDict[givenID].isDash) ? GetEmptySkillSlot() : HandleSkillDrop(GetDashSkill()));
		}
		if (num > -1)
		{
			AssignSkillSlot(num, givenID);
		}
		else
		{
			HandleSkillDrop(stockSkill);
			stockSkill = skillsDict[givenID];
		}
	}
	skillsDict[givenID].SetEmpowered(isEmpowered, EmpowerStatMods.DefaultEmpowerMod);
	lowerHUD.cooldownUI.RefreshEntries();
	newItemNoticeUI.Display(TextManager.GetSkillName(givenID), IconManager.GetSkillIcon(givenID), CooldownUI.GetKeySpriteFromSkillSlot(num, inputDevice), isSkill: true, isSignature, isEmpowered);
	if (isEmpowered)
	{
		SoundManager.PlayAudio("BuyEmpoweredArcana");
	}
	else
	{
		SoundManager.PlayAudio("Powerup");
	}
	if (skillPickUpEventHandlers != null)
	{
		skillPickUpEventHandlers(skillsDict[givenID]);
	}
	AnnounceSkillChanged(skillsDict[givenID]);
}

private int HandleSkillDrop(SkillState givenSkill)
{
	if (givenSkill == null)
	{
		return -1;
	}
	if (skillDropEventHandlers != null)
	{
		skillDropEventHandlers(givenSkill);
	}
	AnnounceSkillChanged(givenSkill);
	Vector3 position = transform.position;
	int amount = 1;
	string skillID = givenSkill.skillID;
	bool isEmpowered = givenSkill.IsEmpowered;
	bool useLifeTime = Application.loadedLevelName.Contains("PvP");
	LootManager.DropSkill(position, amount, skillID, 0f, 0f, null, useLifeTime, isEmpowered);
	givenSkill.SetEmpowered(givenStatus: false, EmpowerStatMods.DefaultEmpowerMod);
	return givenSkill.SetSkillSlot();
}

public void RemoveSkill(SkillState givenSkillState)
{
	if (givenSkillState == null)
	{
		return;
	}
	string skillID = givenSkillState.skillID;
	int num = givenSkillState.SetSkillSlot();
	if (num < 0)
	{
		if (stockSkill.skillID == skillID)
		{
			stockSkill = null;
		}
	}
	else
	{
		AssignSkillSlot(num, string.Empty);
	}
	givenSkillState.SetEmpowered(givenStatus: false, EmpowerStatMods.DefaultEmpowerMod);
	lowerHUD.cooldownUI.RefreshEntries();
	newItemNoticeUI.Display(TextManager.GetSkillName(skillID), IconManager.GetSkillIcon(skillID), null, isSkill: true, givenSkillState.isSignature, givenSkillState.IsEmpowered, acquired: false);
	SoundManager.PlayAudio("Powerup");
	if (skillRemoveEventHandlers != null)
	{
		skillRemoveEventHandlers(givenSkillState);
	}
	AnnounceSkillChanged(givenSkillState);
}

