public void AssignPlayerID(int newPlayerID = -1)
{
	if (GameController.playerScripts == null)
	{
		GameController.playerScripts = new Player[GameController.maxPlayerCount];
	}
	if (newPlayerID != -1)
	{
		playerID = newPlayerID;
		GameController.playerScripts[playerID] = this;
		SetPlayerSortOffset(playerID);
		return;
	}
	for (int i = 0; i < GameController.playerScripts.Length; i++)
	{
		if (GameController.playerScripts[i] == null)
		{
			playerID = i;
			GameController.playerScripts[i] = this;
			SetPlayerSortOffset(playerID);
			break;
		}
	}
}

public static void UpdateActivePlayers()
{
	int num = 0;
	if (GameController.playerScripts[0] != null && GameController.playerScripts[0].gameObject != null)
	{
		num++;
	}
	if (GameController.playerScripts[1] != null && GameController.playerScripts[1].gameObject != null)
	{
		num++;
	}
	if (GameController.activePlayers.Length != num)
	{
		GameController.activePlayers = new Player[num];
	}
	int num2 = 0;
	for (int i = 0; i < GameController.playerScripts.Length; i++)
	{
		if (num2 >= num)
		{
			break;
		}
		if (GameController.playerScripts[i] != null && GameController.playerScripts[i].gameObject != null)
		{
			GameController.activePlayers[num2] = GameController.playerScripts[i];
			num2++;
		}
	}
}

public void SetPlayerSortOffset(int playerID)
{
	if (playerID > 0)
	{
		spriteSorter.yLayerOffset = -1;
	}
}

public static FacingDirection GetInputDirection(ChaosInputDevice inputDev)
{
	Vector2 directionalVector = GetDirectionalVector(inputDev, cardinalDirectionsOnly: true);

		Vector2 directionalVector = GetDirectionalVector(inputDev, cardinalDirectionsOnly: true);
		if (directionalVector.x == 1f)
		{
			return FacingDirection.Right;
		}
		if (directionalVector.x == -1f)
		{
			return FacingDirection.Left;
		}
		if (directionalVector.y == 1f)
		{
			return FacingDirection.Up;
		}
		if (directionalVector.y == -1f)
		{
			return FacingDirection.Down;
		}
		return FacingDirection.Neutral;
	}

	public static Vector2 GetDirectionalVector(ChaosInputDevice inputDev, bool cardinalDirectionsOnly = false)
	{
		Vector2 vector = inputDev.GetMoveVector();
		if (Mathf.Abs(Mathf.Abs(vector.x) - Mathf.Abs(vector.y)) <= diagonalInputDiffRange && !cardinalDirectionsOnly)
		{
			if (vector.x > 0f)
			{
				if (vector.y > 0f)
				{
					vector = new Vector2(1f, 1f);
				}
				else if (vector.y < 0f)
				{
					vector = new Vector2(1f, -1f);
				}
			}
			else if (vector.x < 0f)
			{
				if (vector.y > 0f)
				{
					vector = new Vector2(-1f, 1f);
				}
				else if (vector.y < 0f)
				{
					vector = new Vector2(-1f, -1f);
				}
			}
		}
		else if (Mathf.Abs(vector.x) < Mathf.Abs(vector.y))
		{
			if (vector.y > 0f)
			{
				vector = new Vector2(0f, 1f);
			}
			else if (vector.y < 0f)
			{
				vector = new Vector2(0f, -1f);
			}
		}
		else if (vector.x > 0f)
		{
			vector = new Vector2(1f, 0f);
		}
		else if (vector.x < 0f)
		{
			vector = new Vector2(-1f, 0f);
		}
		return vector.normalized;
	}

