			hud.MiscPing("HourglassUI");
		}
	}

	public FacingDirection SetFacingDirectionBasedOnInput()
	{
		FacingDirection inputDirection = GetInputDirection(inputDevice);
		if (inputDirection != FacingDirection.Neutral)
		{
			facingDirection = inputDirection;
			if (inputDirection == FacingDirection.Left)
			{
				isFacingRight = false;
			}
			else
			{
				isFacingRight = true;
			}
		}
		return inputDirection;
	}

