		if (playerObjTrans != null && playerObjTrans.gameObject != null)
		{
			UnityEngine.Object.Destroy(playerObjTrans.gameObject);
		}
		GameController.playerScripts[playerID] = null;
		GameController.players.Remove(gameObject);
		UpdateActivePlayers();
		BoolVarStat boolVarStat = healthRegenStat;
		boolVarStat.statChangedEventHandlers = (VarStat<bool>.StatChangedEventHandler)Delegate.Remove(boolVarStat.statChangedEventHandlers, new VarStat<bool>.StatChangedEventHandler(OnRegenStatChanged));
		inventory.ClearInventory();
		foreach (SkillState value in skillsDict.Values)
		{
			value.SetEmpowered(givenStatus: false, EmpowerStatMods.DefaultEmpowerMod);
		}
		if (playerDestroyEventHandlers != null)
		{
			playerDestroyEventHandlers(this);
		}
	}

