	public static void ModifySkills(NumVarStatMod givenMod, Player givenPlayer, string statFieldStr, SkillApplyCondition ApplyCondition = null, bool addMod = true)
	{
		if (givenMod == null || givenPlayer == null)
		{
			return;
		}
		if (addMod)
		{
			for (int num = givenPlayer.skillStates.Length - 1; num > -1; num--)
			{
				modifiedSkillState = givenPlayer.skillStates[num];
				if (modifiedSkillState != null && (ApplyCondition == null || ApplyCondition(modifiedSkillState)))
				{
					modifiedSkillState.skillData.AddMod(statFieldStr, givenMod);
				}
			}
		}
		else
		{
			for (int num2 = givenPlayer.skillStates.Length - 1; num2 > -1; num2--)
			{
				modifiedSkillState = givenPlayer.skillStates[num2];
				if (modifiedSkillState != null && (ApplyCondition == null || ApplyCondition(modifiedSkillState)))
				{
					modifiedSkillState.skillData.RemoveMod(statFieldStr, givenMod.ID);
				}
			}
		}
		modifiedSkillState = null;
	}

	public static void ModifySkills(Player givenPlayer, SkillApplyCondition ApplyCondition = null, SkillApplyResult ApplyResult = null, bool givenStatus = true)
	{
		if (givenPlayer == null || ApplyResult == null)
		{
			return;
		}
		for (int num = givenPlayer.skillStates.Length - 1; num > -1; num--)
		{
			modifiedSkillState = givenPlayer.skillStates[num];
			if (ApplyCondition == null || ApplyCondition(modifiedSkillState))
			{
				ApplyResult(modifiedSkillState, givenStatus);
			}
		}
	}

