	public bool UpdateRandSkillsDict(ElementType forceElement = ElementType.Neutral)
	{
		if (randSkillsDict == null)
		{
			randSkillsDict = new Dictionary<SpellBookUI.SkillEquipType, List<string>>();
		}
		randSkillsDict.Clear();
		randSkillsDict[SpellBookUI.SkillEquipType.Basic] = new List<string>();
		randSkillsDict[SpellBookUI.SkillEquipType.Dash] = new List<string>();
		randSkillsDict[SpellBookUI.SkillEquipType.Optional] = new List<string>();
		randSkillsDict[SpellBookUI.SkillEquipType.Signature] = new List<string>();
		foreach (SkillState value in skillsDict.Values)
		{
			if (!value.isUnlocked || (forceElement != ElementType.Neutral && value.element != forceElement))
			{
				continue;
			}
			if (value.isBasic)
			{
				randSkillsDict[SpellBookUI.SkillEquipType.Basic].Add(value.skillID);
				continue;
			}
			if (value.isDash)
			{
				randSkillsDict[SpellBookUI.SkillEquipType.Dash].Add(value.skillID);
				continue;
			}
			randSkillsDict[SpellBookUI.SkillEquipType.Optional].Add(value.skillID);
			if (value.hasSignatureVariant && value.signatureUnlocked)
			{
				randSkillsDict[SpellBookUI.SkillEquipType.Signature].Add(value.skillID);
			}
		}
		if (forceElement != ElementType.Neutral && (randSkillsDict[SpellBookUI.SkillEquipType.Basic].Count == 0 || randSkillsDict[SpellBookUI.SkillEquipType.Dash].Count == 0 || randSkillsDict[SpellBookUI.SkillEquipType.Optional].Count == 0 || randSkillsDict[SpellBookUI.SkillEquipType.Signature].Count == 0))
		{
			return false;
		}
		return true;
	}

