	private void CheckForParry(AttackInfo givenAtkInfo, Entity givenEnt)
	{
		if (givenAtkInfo == null || givenAtkInfo.isStatusEffect || health.GuardNextAtk || (!(fsm.currentState is BaseDashState) && !(currentStateName == SlideState.staticID) && !(currentStateName == ParryState.staticID) && !(currentStateName == "Idle") && (!parryActive || !(currentStateName == "Run"))))
		{
			return;
		}
		parryInputVec = GetInputVector(faceInputVector: false, useAimVector: false, ignoreZero: false);
		if (!(Vector2.Angle(parryInputVec, -givenAtkInfo.attackingVector) > 50f))
		{
			health.GuardNextAtk = true;
			PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Large, givenAtkInfo.attackerPosition, givenAtkInfo.targetPosition);
			CameraController.ShakeCamera(0.1f);
			TimeScaleController.SetTimeScaleDelayOverRealTime(0.0625f, 0.01f, useEaseOut: true, ignoreAllPrevDelays: true);
			movement.dashVector = -parryInputVec;
			fsm.ChangeState(ParryState.staticID, allowSelfTransition: true);
			if (parryEventHandlers != null)
			{
				parryEventHandlers(givenAtkInfo, parryInputVec);
			}
		}
	}

