public class OverheadNumber : MonoBehaviour
{
	public static Color defaultBorderColor = new Color(0f, 0f, 0f, 0.5f);

	public static float globalScaleMultiplier = 1f;

	public Image damageDownIcon;

	public Image damageUpIcon;

	private Text numberText;

	private Outline numberBorder;

	private Image critSplash;

	private Image healCritSplash;

	private Animator anim;

	private Canvas canvas;

	private Transform activeTransform;

	private Vector3 activationPosition = Vector3.zero;

	private Vector3 finalPosition = Vector3.zero;

	private Vector3 xOffset = Vector3.zero;

	private float dynamicScale = 1f;

	private const float flyDist = 1f;

	private bool isRunning;

	private float flyTimePercentage;

	private ChaosQuickStopwatch flyStopwatch = new ChaosQuickStopwatch(0.5f);

	private void Awake()
	{
		anim = GetComponent<Animator>();
		numberText = transform.Find("Canvas/Damage").GetComponent<Text>();
		TextManager.AddUIRef(string.Empty, numberText, useSizing: false);
		numberBorder = transform.Find("Canvas/Damage").GetComponent<Outline>();
		numberBorder.effectColor = defaultBorderColor;
		critSplash = transform.Find("Canvas/CritSplash").GetComponent<Image>();
		critSplash.enabled = false;
		healCritSplash = transform.Find("Canvas/HealCritSplash").GetComponent<Image>();
		healCritSplash.enabled = false;
		activeTransform = null;
		anim.enabled = false;
		canvas = transform.Find("Canvas").GetComponent<Canvas>();
	}

	public void Activate(string displayText, Vector2 originVector, Color fillColor, Color borderColor, Vector3 parentPosition, Transform parentTransform = null, bool activeXval = true, float textScaleVal = 1f, bool isCrit = false, OverheadNumberIcon icon = OverheadNumberIcon.None, CritType critType = CritType.Default)
	{
		damageUpIcon.enabled = false;
		damageDownIcon.enabled = false;
		switch (icon)
		{
		case OverheadNumberIcon.DamageDown:
			damageDownIcon.rectTransform.anchoredPosition = new Vector2(-0.625f - (float)displayText.Length * 0.235f, 0f);
			damageDownIcon.enabled = true;
			break;
		case OverheadNumberIcon.DamageUp:
			damageUpIcon.rectTransform.anchoredPosition = new Vector2(-0.625f - (float)displayText.Length * 0.235f, 0f);
			damageUpIcon.enabled = true;
			break;
		}
		activeTransform = parentTransform;
		activationPosition = ((!(parentTransform == null)) ? parentTransform.position : parentPosition);
		xOffset = ((!activeXval) ? Vector3.zero : (((!(originVector.x - activationPosition.x < 0f)) ? Vector3.left : Vector3.right) * 1f));
		finalPosition = activationPosition + xOffset;
		transform.position = activationPosition;
		dynamicScale = Mathf.Clamp(textScaleVal, 1f, 1.5f);
		numberText.transform.localScale = Vector3.one * dynamicScale * globalScaleMultiplier;
		critSplash.transform.localScale = Vector3.one * dynamicScale * 1.1875f;
		numberText.text = displayText;
		numberText.color = fillColor;
		numberBorder.effectColor = borderColor;
		healCritSplash.enabled = false;
		critSplash.enabled = false;
		if (isCrit)
		{
			if (critType == CritType.Heal)
			{
				healCritSplash.enabled = true;
				critSplash.enabled = false;
			}
			else
			{
				healCritSplash.enabled = false;
				critSplash.enabled = true;
			}
		}
		anim.enabled = true;
		anim.Play("OverheadText", -1, 0f);
		canvas.enabled = true;
		flyTimePercentage = 0f;
		flyStopwatch.IsRunning = true;
		isRunning = true;
		StartCoroutine(LerpPosition());
	}

	public void Deactivate()
	{
		anim.enabled = false;
		canvas.enabled = false;
		flyStopwatch.IsRunning = false;
		isRunning = false;
	}

	private IEnumerator LerpPosition()
	{
		while (isRunning)
		{
			flyTimePercentage = flyStopwatch.TimePercentage;
			transform.position = Vector3.Lerp(activationPosition, finalPosition, flyTimePercentage);
			if (flyTimePercentage >= 1f)
			{
				isRunning = false;
			}
			yield return null;
		}
	}
}
