public class OverheadNumberPool : MonoBehaviour
{
	public class DisplayQueueObject
	{
		public string displayString;

		public Vector2 originVector;

		public Color fillColor;

		public Color borderColor;

		public Vector3 parentPosition;

		public Transform parentTransform;

		public float scaleValue;

		public bool isCritical;

		public string appendString;

		public OverheadNumberIcon icon;

		public CritType critType;

		public DisplayQueueObject(string newDisplay, Vector2 newOrigin, Color newFill, Color newBorder, Vector3 newPos, Transform newTrans, float newScale, bool newCrit, OverheadNumberIcon newIcon, CritType newCritType = CritType.Default)
		{
			displayString = newDisplay;
			originVector = newOrigin;
			fillColor = newFill;
			borderColor = newBorder;
			parentPosition = newPos;
			parentTransform = newTrans;
			scaleValue = newScale;
			isCritical = newCrit;
			icon = newIcon;
			critType = newCritType;
		}
	}

	public static bool showNumbers = true;

	public static List<DisplayQueueObject> damageNumberList;

	private static int listCounter;

	public static Dictionary<int, DisplayQueueObject> idDict;

	private static DisplayQueueObject currentNum;

	private static DisplayQueueObject incomingNum;

	private static int damageOutCurrent;

	private static int damageOutIncoming;

	private static int listCount;

	private static int incomingID;

	public static int overheadNumberCount;

	public static int overheadNumberIndex;

	private static List<OverheadNumber> overheadNumberObjs;

	private static GameObject overheadNumberPrefab;

	private static OverheadNumberPool instance;

	public static OverheadNumberPool Instance => instance;

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Initialize();
		Object.DontDestroyOnLoad(gameObject);
	}

	public static void DisplayOverheadNumber(string displayText, Vector2 originVector, Color fillColor, Color borderColor, Vector3 parentPosition, Transform parentTransform, float scaleVal = 1f, bool showCritSplash = false, OverheadNumberIcon icon = OverheadNumberIcon.None, CritType critType = CritType.Default)
	{
		if (showNumbers)
		{
			damageNumberList.Add(new DisplayQueueObject(displayText, originVector, fillColor, borderColor, parentPosition, parentTransform, scaleVal, showCritSplash, icon, critType));
		}
	}

	private static OverheadNumber GetOverheadNumber()
	{
		overheadNumberIndex++;
		if (overheadNumberIndex >= overheadNumberCount)
		{
			overheadNumberIndex = 0;
		}
		return overheadNumberObjs[overheadNumberIndex];
	}

	private void Initialize()
	{
		overheadNumberPrefab = ChaosBundle.Get("Assets/Prefabs/Effects/OverheadNumber.prefab");
		overheadNumberObjs = new List<OverheadNumber>();
		overheadNumberIndex = 0;
		overheadNumberCount = 40;
		for (int i = 0; i < overheadNumberCount; i++)
		{
			overheadNumberObjs.Add(Object.Instantiate(overheadNumberPrefab, transform).GetComponent<OverheadNumber>());
		}
		damageNumberList = new List<DisplayQueueObject>();
		idDict = new Dictionary<int, DisplayQueueObject>();
	}

	public void LateUpdate()
	{
		SumAllNumbers();
		DisplayAllNumbers();
	}

	private void SumAllNumbers()
	{
		listCount = damageNumberList.Count;
		for (listCounter = 0; listCounter < listCount; listCounter++)
		{
			incomingNum = damageNumberList[listCounter];
			incomingID = incomingNum.parentTransform.GetInstanceID();
			if (idDict.ContainsKey(incomingID))
			{
				currentNum = idDict[incomingID];
				if (!(currentNum.fillColor != incomingNum.fillColor) && int.TryParse(currentNum.displayString, out damageOutCurrent) && int.TryParse(incomingNum.displayString, out damageOutIncoming))
				{
					currentNum.displayString = (damageOutCurrent + damageOutIncoming).ToString();
					if (currentNum.scaleValue < incomingNum.scaleValue)
					{
						currentNum.scaleValue = incomingNum.scaleValue;
					}
					if (incomingNum.isCritical)
					{
						currentNum.isCritical = true;
					}
					if (incomingNum.appendString != string.Empty)
					{
						currentNum.appendString = incomingNum.appendString;
					}
				}
			}
			else
			{
				idDict.Add(incomingID, incomingNum);
			}
		}
		damageNumberList.Clear();
	}

	private void DisplayAllNumbers()
	{
		foreach (DisplayQueueObject value in idDict.Values)
		{
			GetOverheadNumber().Activate(value.appendString + value.displayString, value.originVector, value.fillColor, value.borderColor, value.parentPosition, value.parentTransform, activeXval: true, value.scaleValue, value.isCritical, value.icon, value.critType);
		}
		idDict.Clear();
	}
}

