public class FrozenOverlay : MonoBehaviour
{
	public static ParticleSystemOverride pEffectOverrides = new ParticleSystemOverride
	{
		startSpeed = 15f,
		startLifetime = 0.33f
	};

	private static Vector3 frozenOffset = new Vector3(0f, 0.5f);

	private Transform targetTrans;

	private Vector2 targetPos;

	public float lifeTime;

	private int lifeStopwatchID = -1;

	private void Start()
	{
		LetItGo();
	}

	public void Freeze(Transform givenTrans)
	{
		gameObject.SetActive(value: true);
		lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		targetTrans = givenTrans;
	}

	public void LateUpdate()
	{
		if (targetTrans != null && !ChaosStopwatch.Check(lifeStopwatchID))
		{
			transform.position = targetTrans.position;
		}
		else
		{
			LetItGo();
		}
	}

	public void LetItGo(bool refreeze = false)
	{
		if (!refreeze && targetTrans != null)
		{
			targetPos = targetTrans.position + frozenOffset;
			PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(15, targetPos, pEffectOverrides);
			SoundManager.PlayAudioWithDistance("IceBreak", targetPos);
		}
		lifeStopwatchID = -1;
		targetTrans = null;
		gameObject.SetActive(value: false);
	}
}
