public class EmoteRandomizer : MonoBehaviour
{
	private ChaosQuickStopwatch emoteTimer0;

	private ChaosQuickStopwatch emoteTimer1;

	private ChaosQuickStopwatch emoteTimer2;

	private ChaosQuickStopwatch emoteTimer3;

	private ChaosQuickStopwatch emoteTimer4;

	private ChaosQuickStopwatch emoteTimer5;

	private int emotePerInterval = 1;

	private Vector3 emoteOffset = new Vector3(0f, 2.25f, 0f);

	private EmoteType[] validEmotes = new EmoteType[7]
	{
		EmoteType.Alert,
		EmoteType.AwwYis,
		EmoteType.Laugh,
		EmoteType.Hum,
		EmoteType.OMG,
		EmoteType.Woo,
		EmoteType.Heart
	};

	private void Awake()
	{
		emoteTimer0 = new ChaosQuickStopwatch(0.1f);
		emoteTimer1 = new ChaosQuickStopwatch(0.1f);
		emoteTimer2 = new ChaosQuickStopwatch(0.2f);
		emoteTimer3 = new ChaosQuickStopwatch(0.2f);
		emoteTimer4 = new ChaosQuickStopwatch(0.4f);
		emoteTimer5 = new ChaosQuickStopwatch(0.4f);
	}

	private void Update()
	{
		HandleTimer(emoteTimer0);
		HandleTimer(emoteTimer1);
		HandleTimer(emoteTimer2);
		HandleTimer(emoteTimer3);
		HandleTimer(emoteTimer4);
		HandleTimer(emoteTimer5);
	}

	private void HandleTimer(ChaosQuickStopwatch timer)
	{
		if (!timer.IsRunning)
		{
			for (int i = 0; i < emotePerInterval; i++)
			{
				PoolManager.GetPoolItem<EmoteEmitter>().Emit(validEmotes.GetRandomValue(), 1, transform.GetChild(Random.Range(0, transform.childCount - 1)).position + emoteOffset);
			}
			timer.SetDelay(Random.Range(0.35f, 0.75f), stopCurrent: false, autoStart: true);
		}
	}
}
