	private void Awake()
	{
		Transform transform = base.transform.Find("SnowEmitter");
		trailEmitter = transform.GetComponent<ParticleSystem>();
	}

	public void EmitTrail(Vector2 startPos, Vector2 endPos, int givenParticleCount = 0)
	{
		float num = Vector2.Distance(startPos, endPos);
