using UnityEngine;

public class CircleOutlineEffect : MonoBehaviour
{
	private Animator anim;

	private bool playing;

	private float animEndTime = 1f;

	private float animStartTime;

	private bool firstFrameSkipped;

	private Material spriteMaterial;

	private float dissolveThreshold = 0.6f;

	private float dissolveTime;

	private void Awake()
	{
		anim = GetComponent<Animator>();
		spriteMaterial = GetComponentInChildren<SpriteRenderer>().material;
	}

	public void Update()
	{
		if (playing && firstFrameSkipped)
		{
			float animTime = anim.GetAnimTime();
			if (animTime >= animEndTime)
			{
				Reset();
			}
			else if (animTime >= dissolveTime)
			{
				spriteMaterial.SetFloat("_DissolveAmount", Globals.LerpWithRange(dissolveTime, animEndTime, animTime));
			}
		}
	}

	public void LateUpdate()
	{
		if (playing && !firstFrameSkipped)
		{
			firstFrameSkipped = true;
		}
	}

	public void Play(Vector3 position, float animSpeed = 1f, float animStartTime = 0f, float animEndTime = 1f)
	{
		transform.position = position;
		this.animEndTime = animEndTime;
		this.animStartTime = animStartTime;
		anim.speed = animSpeed;
		dissolveTime = animEndTime * dissolveThreshold;
		anim.Play("Grow", -1, animStartTime);
		playing = true;
		firstFrameSkipped = false;
		spriteMaterial.SetFloat("_DissolveAmount", 0f);
		transform.Rotate(Vector3.forward, 90 * Random.Range(0, 3));
	}

	public void Reset()
	{
		playing = false;
		firstFrameSkipped = false;
		anim.speed = 1f;
		animEndTime = 1f;
		animStartTime = 1f;
		dissolveTime = dissolveThreshold;
		anim.Play("Idle", -1, 0f);
		spriteMaterial.SetFloat("_DissolveAmount", 0f);
	}
}
