public class ProjectileNegator : MonoBehaviour
{
	private static GameObject _prefab;

	private bool destroyOnDisable = true;

	public CircleCollider2D negateCircleCollider2D;

	public BoxCollider2D negateBoxCollider2D;

	public NegateProjectiles negateScript;

	public bool trackingAttack;

	public Attack mimicAttack;

	private CircleCollider2D atkCircleCollider;

	private BoxCollider2D atkBoxCollider;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ProjectileNegator.prefab");
			}
			return _prefab;
		}
	}

	public void Disable()
	{
		negateCircleCollider2D.enabled = false;
		negateBoxCollider2D.enabled = false;
		negateScript.enabled = false;
		enabled = false;
		trackingAttack = false;
		if (destroyOnDisable)
		{
			Object.Destroy(gameObject);
		}
	}

	public void Update()
	{
		if (trackingAttack)
		{
			MimicAttack();
		}
	}

	public void MimicAttack()
	{
		if (mimicAttack == null)
		{
			if (trackingAttack)
			{
				Disable();
			}
			return;
		}
		if (atkCircleCollider != null)
		{
			negateCircleCollider2D.radius = atkCircleCollider.radius;
			negateCircleCollider2D.transform.position = atkCircleCollider.transform.position;
			negateCircleCollider2D.offset = atkCircleCollider.offset;
			negateCircleCollider2D.enabled = atkCircleCollider.enabled;
		}
		if (atkBoxCollider != null)
		{
			negateBoxCollider2D.size = atkBoxCollider.size;
			negateBoxCollider2D.transform.position = atkBoxCollider.transform.position;
			negateBoxCollider2D.offset = atkBoxCollider.offset;
			negateBoxCollider2D.enabled = atkBoxCollider.enabled;
		}
	}

	public void Enable(Attack attack = null)
	{
		negateScript.enabled = true;
		if (!(attack == null))
		{
			mimicAttack = attack;
			trackingAttack = true;
			if (mimicAttack.collider is CircleCollider2D)
			{
				atkCircleCollider = (CircleCollider2D)mimicAttack.collider;
			}
			if (mimicAttack.collider is BoxCollider2D)
			{
				atkBoxCollider = (BoxCollider2D)mimicAttack.collider;
			}
		}
	}
}
