	public MindControlCloudDotEffect(Entity givenEnt, float givenDuration, bool useBuffs = false)
		: base(string.Empty, mindControlStr, 0, givenEnt, null)
	{
		useInterval = false;
		damageInterval = givenDuration;
		damageStopwatchID = ChaosStopwatch.Begin(damageInterval);
		applyBuffs = useBuffs;
	}

	public override bool Update()
	{
		if (checkStopwatch.IsRunning)
		{
			return false;
		}
		checkStopwatch.IsRunning = true;
		if (ChaosStopwatch.Check(damageStopwatchID) || parentEntity == null || parentEntity.health == null || parentEntity.health.healthStat.CurrentValue <= 0f)
		{
			CleanUp();
			return true;
		}
		return false;
	}

	public override void Init()
	{
		SetBuffStatus(parentEntity as Enemy, givenStatus: true);
		SetEffectStatus(givenStatus: true);
	}

	public override void CleanUp()
	{
		SetBuffStatus(parentEntity as Enemy, givenStatus: false);
		SetEffectStatus(givenStatus: false);
	}

	public override void Refresh(int hits = 0, float time = 0f)
	{
		damageStopwatchID = ChaosStopwatch.Begin(damageInterval);
	}

	private void SetEffectStatus(bool givenStatus)
	{
		if (parentEntity == null)
		{
			return;
		}
		if (givenStatus)
		{
			if (heartEffect == null)
			{
				heartEffect = Globals.ChaosInst<BaseEffect>(MindControlCloudEffect.Prefab, parentEntity.transform.parent, parentEntity.hurtBoxTransform.position);
				heartEffect.entity = parentEntity;
			}
			if (applyBuffs && windEffect == null)
			{
				windEffect = Globals.ChaosInst<BaseEffect>(BabylonScalesEffect.Prefab, parentEntity.transform.parent, parentEntity.hurtBoxTransform.position);
				windEffect.entity = parentEntity;
				(windEffect as BabylonScalesEffect).isBuff = isBuff;
			}
		}
		else
		{
			if (heartEffect != null)
			{
				heartEffect.Disable();
			}
			if (windEffect != null)
			{
				windEffect.Disable();
			}
		}
	}

	private void SetBuffStatus(Enemy givenEnemy, bool givenStatus)
	{
		if (givenEnemy == null)
		{
			return;
		}
		givenEnemy.SetAffiliation(!givenStatus);
		if (applyBuffs)
		{
			if (givenStatus)
			{
				givenEnemy.cooldownManager.ResetCooldowns();
			}
