using System.Collections;
using System.Linq;

public class RandRunMod : RunMod
{
	public static string staticID = "RandomRun";

	public RandRunMod()
	{
		modID = staticID;
		useOnLoadComplete = true;
		useOnLevelWasLoaded = true;
		activateImmediately = false;
	}

	public override void Activate()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null))
			{
				player.RandomizeBuild(player.outfitID != "Pride");
			}
		}
		RunData.Reset();
		RunData.InitRun();
		LootManager.Reset();
	}

	public override void OnLoadComplete()
	{
		base.OnLoadComplete();
		GameController.runModifier.StartCoroutine(AnnounceRandItems());
		useOnLoadComplete = false;
	}

	public override void OnLevelWasLoaded()
	{
		base.OnLevelWasLoaded();
		Activate();
		useOnLevelWasLoaded = false;
	}

	private IEnumerator AnnounceRandItems()
	{
		yield return Globals.waitForQuarter;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null) && player.inventory != null && player.inventory.itemDict != null && player.inventory.itemDict.Keys.Count != 0)
			{
				player.newItemNoticeUI.Display(TextManager.GetItemName(player.inventory.itemDict.Values.First().ID), IconManager.GetItemIcon(player.inventory.itemDict.Values.First().ID));
			}
		}
	}
}

